        return execute_std_backend(task, input_value, output_value);
    }
    if (selected == "tbb") {
        if (task.task_type == UXB_RT_TASK_PARALEL && tbb_backend_available())
            return execute_tbb_backend(task, input_value, output_value);
        return execute_std_backend(task, input_value, output_value);
    }
    if (task.task_type == UXB_RT_TASK_PARALEL && tbb_backend_available())
        return execute_tbb_backend(task, input_value, output_value);
    if (libuv_backend_available())
        return execute_libuv_backend(task, input_value, output_value);
    return execute_std_backend(task, input_value, output_value);
}

std::string active_backend_name() {
    const std::string selected = mode();
    if (selected == "std") return "std";
    if (selected == "libuv") return libuv_backend_available() ? "libuv" : "std(fallback)";
    if (selected == "tbb") return tbb_backend_available() ? "tbb+std" : "std(fallback)";
    if (libuv_backend_available() && tbb_backend_available()) return "auto(libuv+tbb)";
    if (libuv_backend_available()) return "auto(libuv)";
    if (tbb_backend_available()) return "auto(tbb+std)";
    return "auto(std)";
}

} // namespace uxb
#include "std_backend.h"
#include <exception>
#include <thread>

namespace uxb {

static int invoke_callback(const TaskRecord& task, int input_value, int* output_value) {
    try {
        return task.callback(task.slot_id, input_value, output_value, task.user_data);
    } catch (const std::exception& ex) {
        RuntimeState::instance().set_error(std::string("callback exception: ") + ex.what());
    } catch (...) {
        RuntimeState::instance().set_error("callback exception: unknown");
    }
    return UXB_RT_FAILURE;
}

int execute_std_backend(const TaskRecord& task, int input_value, int* output_value) {
    if (task.task_type == UXB_RT_TASK_EVENT || task.task_type == UXB_RT_TASK_PIPE) {
        return invoke_callback(task, input_value, output_value);
    }
    int rc = UXB_RT_FAILURE;
    std::thread worker([&]() { rc = invoke_callback(task, input_value, output_value); });
    worker.join();
    return rc;
}

} // namespace uxb

