}

UXB_RT_API int64_t UXB_RT_CDECL __uxb_rt_print_newline(void) {
    uxb::console_write("\n");
    return 1;
}

UXB_RT_API int64_t UXB_RT_CDECL __uxb_rt_print_f64(double value) {
