1	// S-030 Faz 2A — native gorev calisma zamani, ABI v2.
2	// Tasarim: docs/tasarim/UXB_S030_FAZ2A_NATIVE_ASYNC_PLANI_20260925_TR.md
3	// Mete kararlari: K4 (sinirli isci havuzu, AUTO = mantiksal CPU, --task-workers N,
4	// bekleyen isci kuyruktan is calistirir), K5 (normal kapanis gorevleri bekler;
5	// okunmamis gorev hatasi hata cikisina yazilir, cikis kodu basarisiz), K6
6	// (isbirlikci iptal; STATUS=CANCELLED, ERRORTEXT="CANCELLED"; JOIN/RESULT iptali
7	// cagirana aktarir; tekrar CANCEL zararsiz), K9 (PRINT ayri dosyada).
8	//
9	// Kod uretimi sozlesmesi (thunk): derleyici SPAWN hedefi olan her lane icin
10	//     int64_t thunk(void* block)
11	// uretir. block[0..7] sonuc yuvasidir (thunk yazar), block[8..] argumanlardir
12	// (her biri 8 bayt; tamsayi degeri, F64 bit deseni ya da STRING icin kopyalanmis
13	// metnin adresi). Thunk 0 doner; yakalanmamis THROW'u lane icinden
14	// __uxb_rt_task_fail_* ile bildirir. Deger turleri koleksiyonlarla ayni:
15	// 0=VOID, 1=I64, 2=F64, 3=STRING.
16	
17	#include "uxb_runtime.h"
18	#include "uxb_runtime_print.h"
19	
20	#include <algorithm>
21	#include <atomic>
22	#include <condition_variable>
23	#include <cstdio>
24	#include <cstdlib>
25	#include <cstring>
26	#include <deque>
27	#include <memory>
28	#include <mutex>
29	#include <string>
30	#include <thread>
31	#include <vector>
32	
33	#if defined(_WIN32)
34	#include <process.h>
35	#include <windows.h>
36	#endif
37	
38	namespace {
39	
40	typedef int64_t (UXB_RT_CDECL *uxb_task_thunk_v2)(void* block);
41	
42	enum TaskStateV2 { TS_PENDING = 0, TS_RUNNING = 1, TS_DONE = 2, TS_ERROR = 3, TS_CANCELLED = 4 };
43	const int64_t kValueVoid = 0;
44	const int64_t kValueString = 3;
45	
46	struct TaskRunV2 {
47	    int64_t id = 0;
48	    std::string name;
49	    int state = TS_PENDING;
50	    uxb_task_thunk_v2 thunk = nullptr;
51	    std::vector<unsigned char> block;
52	    int64_t resultKind = kValueVoid;
53	    int64_t resultBits = 0;
54	    std::string resultText;
55	    std::string errorText;
56	    bool errorObserved = false;
57	    std::atomic<bool> cancelRequested{false};
58	    std::vector<std::string> argTexts;   // STRING argumanlarinin gorev omrunce sahibi kopyalari
59	};
60	
61	struct TaskGroupV2 {
62	    std::vector<int64_t> members;
63	};
64	
65	// Paylasilan durum bilerek yigindan alinir ve HIC yok edilmez: ANSI exit() statik yikicilari
66	// calistirir; o sirada hala calisan isciler yok edilmis bir mutex'e dokunur ya da birlesmemis
67	// std::thread yikicisi std::terminate cagirir (olumcul JOIN hatasi = exit(1) yolu).
68	struct TaskRuntimeStateV2 {
69	    std::mutex mutex;
70	    std::condition_variable workAvailable;
71	    std::condition_variable taskFinished;
72	    std::deque<int64_t> queue;
73	    std::vector<std::unique_ptr<TaskRunV2>> tasks;     // id = indeks + 1
74	    std::vector<std::unique_ptr<TaskGroupV2>> groups;  // id = indeks + 1
75	#if defined(_WIN32)
76	    std::vector<HANDLE> workers;       // _beginthreadex: yigin boyutu acikca verilebilsin diye
77	#else
78	    std::vector<std::thread> workers;
79	#endif
80	    bool poolStarted = false;
81	    bool stopping = false;
82	    int workerCount = 0;
83	};
84	TaskRuntimeStateV2& S() {
85	    static TaskRuntimeStateV2* state = new TaskRuntimeStateV2();
86	    return *state;
87	}
88	#define g_mutex (S().mutex)
89	#define g_workAvailable (S().workAvailable)
90	#define g_taskFinished (S().taskFinished)
91	#define g_queue (S().queue)
92	#define g_tasks (S().tasks)
93	#define g_groups (S().groups)
94	#define g_workers (S().workers)
95	#define g_poolStarted (S().poolStarted)
96	#define g_stopping (S().stopping)
97	#define g_workerCount (S().workerCount)
98	
99	thread_local TaskRunV2* tl_current = nullptr;
100	std::atomic<bool> g_poolActive{false};   // K9: konsol satir tamponu bu bayrakla devreye girer (kilitsiz okuma)
101	
102	// STATUS/ERRORTEXT metin donusleri: cagiran is parcacigina ozel halka; ayni ifadede iki cagri
103	// (ornek: t.STATUS + t.ERRORTEXT) birbirini ezmez. uxb_runtime_mir.cpp hold_text ile ayni kural.
104	thread_local std::string tl_textRing[16];
105	thread_local unsigned tl_textIndex = 0;
106	const char* hold_task_text(const std::string& value) {
107	    std::string& slot = tl_textRing[tl_textIndex++ % 16];
108	    slot = value;
109	    return slot.c_str();
110	}
111	
112	const char* state_name(int s) {
113	    switch (s) {
114	    case TS_PENDING: return "PENDING";
115	    case TS_RUNNING: return "RUNNING";
116	    case TS_DONE: return "DONE";
117	    case TS_ERROR: return "ERROR";
118	    case TS_CANCELLED: return "CANCELLED";
119	    default: return "PENDING";
120	    }
121	}
122	
123	bool is_finished(int s) { return s == TS_DONE || s == TS_ERROR || s == TS_CANCELLED; }
124	
125	[[noreturn]] void runtime_fatal(const std::string& message) {
126	    uxb::console_flush_current_thread();
127	    std::fputs(message.c_str(), stderr);
128	    std::fputc('\n', stderr);
129	    std::fflush(stderr);
130	    std::exit(1);
131	}
132	
133	// Kilit tutulurken cagrilir.
134	TaskRunV2* task_at_locked(int64_t handle) {
135	    if (handle <= 0) return nullptr;
136	    const std::size_t idx = static_cast<std::size_t>(handle - 1);
137	    if (idx >= g_tasks.size()) return nullptr;
138	    return g_tasks[idx].get();
139	}
140	
141	TaskGroupV2* group_at_locked(int64_t handle) {
142	    if (handle <= 0) return nullptr;
143	    const std::size_t idx = static_cast<std::size_t>(handle - 1);
144	    if (idx >= g_groups.size()) return nullptr;
145	    return g_groups[idx].get();
146	}
147	
148	std::atomic<int> g_embeddedWorkers{0};   // --task-workers N (derleyici gomer); 0 = verilmedi
149	
150	// Oncelik: UXB_TASK_WORKERS ortam degiskeni > derleyicinin gomdugu --task-workers > mantiksal CPU (K4).
151	int configured_worker_count() {
152	    const char* raw = std::getenv("UXB_TASK_WORKERS");
153	    if (raw && *raw) {
154	        const long v = std::strtol(raw, nullptr, 10);
155	        if (v >= 1 && v <= 1024) return static_cast<int>(v);
156	    }
157	    const int embedded = g_embeddedWorkers.load();
158	    if (embedded >= 1) return embedded;
159	    const unsigned hw = std::thread::hardware_concurrency();
160	    return hw == 0 ? 4 : static_cast<int>(hw);
161	}
162	
163	// Gorevi calistirir. Kilit TUTULMADAN cagrilir.
164	void run_task(TaskRunV2* t) {
165	    {
166	        std::lock_guard<std::mutex> lock(g_mutex);
167	        if (t->cancelRequested.load()) {
168	            // K6: baslamamis gorev hic calismadan CANCELLED olur.
169	            t->state = TS_CANCELLED;
170	            t->errorText = "CANCELLED";
171	            g_taskFinished.notify_all();
172	            return;
173	        }
174	        t->state = TS_RUNNING;
175	    }
176	    TaskRunV2* previous = tl_current;
177	    tl_current = t;
178	    std::string failure;
179	    try {
180	        t->thunk(t->block.data());
181	    } catch (const std::exception& ex) {
182	        failure = std::string("native gorev ic hatasi: ") + ex.what();
183	    } catch (...) {
184	        failure = "native gorev ic hatasi";
185	    }
186	    tl_current = previous;
187	    // K9: gorevin yarim kalan satiri (PRINT x; ile biten) gorev bitiminde yazilir, baska gorevle karismaz.
188	    uxb::console_flush_current_thread();
189	
190	    std::lock_guard<std::mutex> lock(g_mutex);
191	    if (!failure.empty() && t->errorText.empty()) t->errorText = failure;
192	    if (!t->errorText.empty() && t->state == TS_RUNNING) {
193	        t->state = (t->errorText == "CANCELLED") ? TS_CANCELLED : TS_ERROR;
194	    } else if (t->state == TS_RUNNING) {
195	        std::memcpy(&t->resultBits, t->block.data(), sizeof(int64_t));
196	        if (t->resultKind == kValueString) {
197	            // Lane sonucu isci is parcacigina ozel metin halkasinda; gorev kaydina kopyalanir.
198	            const char* p = nullptr;
199	            std::memcpy(&p, &t->resultBits, sizeof(p));
200	            t->resultText = p ? std::string(p) : std::string();
201	        }
202	        t->state = TS_DONE;
203	    }
204	    g_taskFinished.notify_all();
205	}
206	
207	void worker_main() {
208	    for (;;) {
209	        TaskRunV2* next = nullptr;
210	        {
211	            std::unique_lock<std::mutex> lock(g_mutex);
212	            g_workAvailable.wait(lock, [] { return g_stopping || !g_queue.empty(); });
213	            if (g_queue.empty()) {
214	                if (g_stopping) return;
215	                continue;
216	            }
217	            next = task_at_locked(g_queue.front());
218	            g_queue.pop_front();
219	        }
220	        if (next) run_task(next);
221	    }
222	}
223	
224	#if defined(_WIN32)
225	unsigned __stdcall worker_entry_win32(void*) {
226	    worker_main();
227	    return 0;
228	}
229	#endif
230	
231	void ensure_pool_locked() {
232	    if (g_poolStarted) return;
233	    g_poolStarted = true;
234	    g_poolActive.store(true);
235	    g_workerCount = configured_worker_count();
236	    for (int i = 0; i < g_workerCount; ++i) {
237	#if defined(_WIN32)
238	        // Isci yigini 8 MB: ana is parcaciginin (1 MB PE varsayilani) ve C++ varsayilaninin ustunde; gorev
239	        // govdesindeki derin ozyineleme ana programla ayni ya da daha genis alan bulur.
240	        const uintptr_t h = _beginthreadex(nullptr, 8u * 1024u * 1024u, &worker_entry_win32, nullptr, STACK_SIZE_PARAM_IS_A_RESERVATION, nullptr);
241	        if (h == 0) runtime_fatal("native: gorev iscisi baslatilamadi");
242	        g_workers.push_back(reinterpret_cast<HANDLE>(h));
243	#else
244	        g_workers.emplace_back(worker_main);
245	#endif
246	    }
247	}
248	
249	// K4: bekleyen is parcacigi, beklenen gorev bitene kadar kuyruktan is calistirir
250	// (ic ice SPAWN'da tum isciler birbirini bekleyip kilitlenmesin).
251	void wait_finished(int64_t handle) {
252	    for (;;) {
253	        TaskRunV2* toRun = nullptr;
254	        {
255	            std::unique_lock<std::mutex> lock(g_mutex);
256	            TaskRunV2* t = task_at_locked(handle);
257	            if (!t || is_finished(t->state)) return;
258	            if (!g_queue.empty()) {
259	                toRun = task_at_locked(g_queue.front());
260	                g_queue.pop_front();
261	            } else {
262	                g_taskFinished.wait(lock);
263	                continue;
264	            }
265	        }
266	        if (toRun) run_task(toRun);
267	    }
268	}
269	
270	std::string failure_message_locked(TaskRunV2* t) {
271	    if (t->state == TS_CANCELLED) return "gorev iptal edildi (" + t->name + "): CANCELLED";
272	    return "gorev hatasi (" + t->name + "): " + t->errorText;
273	}
274	
275	int64_t result_value_locked(TaskRunV2* t) {
276	    if (t->resultKind == kValueString) {
277	        const char* p = t->resultText.c_str();   // gorev kaydinin omru boyunca (surec) gecerli
278	        int64_t bits = 0;
279	        std::memcpy(&bits, &p, sizeof(p));
280	        return bits;
281	    }
282	    return t->resultBits;
283	}
284	
285	}  // namespace
