287	UXB_RT_API int64_t UXB_RT_CDECL __uxb_rt_task_spawn(void* thunk, const void* argblock, int64_t bytes, const char* name, int64_t resultKind, int64_t stringArgMask) {
288	    if (!thunk) runtime_fatal("native: SPAWN: gorev giris noktasi yok");
289	    if (bytes < 8) bytes = 8;
290	    auto t = std::make_unique<TaskRunV2>();
291	    t->name = name ? name : "";
292	    t->thunk = reinterpret_cast<uxb_task_thunk_v2>(thunk);
293	    t->resultKind = resultKind;
294	    t->block.assign(static_cast<std::size_t>(bytes), 0);
295	    if (argblock) std::memcpy(t->block.data(), argblock, static_cast<std::size_t>(bytes));
296	    // STRING argumanlari (bit i => block[8 + 8*i]) cagiranin gecici metnine isaret eder;
297	    // gorev baslamadan once kaydin sahip oldugu kopyaya yonlendirilir.
298	    const int64_t argSlots = (bytes - 8) / 8;
299	    for (int64_t i = 0; i < argSlots && i < 62; ++i) {
300	        if ((stringArgMask >> i) & 1) {
301	            const char* p = nullptr;
302	            std::memcpy(&p, t->block.data() + 8 + 8 * i, sizeof(p));
303	            t->argTexts.emplace_back(p ? p : "");
304	        } else {
305	            t->argTexts.emplace_back();
306	        }
307	    }
308	    for (int64_t i = 0; i < argSlots && i < 62; ++i) {
309	        if ((stringArgMask >> i) & 1) {
310	            const char* owned = t->argTexts[static_cast<std::size_t>(i)].c_str();
311	            std::memcpy(t->block.data() + 8 + 8 * i, &owned, sizeof(owned));
312	        }
313	    }
314	    std::lock_guard<std::mutex> lock(g_mutex);
315	    ensure_pool_locked();
316	    t->id = static_cast<int64_t>(g_tasks.size()) + 1;
317	    const int64_t id = t->id;
318	    g_tasks.push_back(std::move(t));
319	    g_queue.push_back(id);
320	    g_workAvailable.notify_one();
321	    return id;
322	}
323	
324	UXB_RT_API int64_t UXB_RT_CDECL __uxb_rt_task_fail_cstr(const char* message) {
325	    if (!tl_current) runtime_fatal(std::string("uncaught THROW ") + (message ? message : ""));
326	    std::lock_guard<std::mutex> lock(g_mutex);
327	    if (tl_current->errorText.empty()) tl_current->errorText = std::string("native: uncaught THROW ") + (message ? message : "");
328	    return 0;
329	}
330	
331	UXB_RT_API int64_t UXB_RT_CDECL __uxb_rt_task_fail_i64(int64_t value) {
332	    return __uxb_rt_task_fail_cstr(std::to_string(value).c_str());
333	}
334	
335	// K6 iptal noktasi: 1 = gorev iptal istendi, lane donmeli (kod uretimi donus yolunu uretir).
336	UXB_RT_API int64_t UXB_RT_CDECL __uxb_rt_task_cancel_point(void) {
337	    TaskRunV2* t = tl_current;
338	    if (!t || !t->cancelRequested.load()) return 0;
339	    std::lock_guard<std::mutex> lock(g_mutex);
340	    if (t->errorText.empty()) t->errorText = "CANCELLED";
341	    return 1;
342	}
343	
344	UXB_RT_API int64_t UXB_RT_CDECL __uxb_rt_task_wait(int64_t handle) {
345	    {
346	        std::lock_guard<std::mutex> lock(g_mutex);
347	        if (!task_at_locked(handle)) runtime_fatal("TASK.WAIT(): bos (NULL) gorev tutamaci");
348	    }
349	    wait_finished(handle);
350	    return 0;
351	}
352	
353	static int64_t join_or_result(int64_t handle, const char* what) {
354	    {
355	        std::lock_guard<std::mutex> lock(g_mutex);
356	        if (!task_at_locked(handle)) runtime_fatal(std::string(what) + ": bos (NULL) gorev tutamaci");
357	    }
358	    wait_finished(handle);
359	    std::lock_guard<std::mutex> lock(g_mutex);
360	    TaskRunV2* t = task_at_locked(handle);
361	    if (t->state == TS_ERROR || t->state == TS_CANCELLED) {
362	        t->errorObserved = true;
363	        runtime_fatal(failure_message_locked(t));
364	    }
365	    return result_value_locked(t);
366	}
367	
368	UXB_RT_API int64_t UXB_RT_CDECL __uxb_rt_task_join(int64_t handle) { return join_or_result(handle, "TASK.JOIN()"); }
369	UXB_RT_API int64_t UXB_RT_CDECL __uxb_rt_task_result(int64_t handle) { return join_or_result(handle, "TASK.RESULT"); }
370	
371	UXB_RT_API int64_t UXB_RT_CDECL __uxb_rt_task_cancel(int64_t handle) {
372	    std::lock_guard<std::mutex> lock(g_mutex);
373	    TaskRunV2* t = task_at_locked(handle);
374	    if (!t) runtime_fatal("TASK.CANCEL(): bos (NULL) gorev tutamaci");
375	    if (!is_finished(t->state)) t->cancelRequested.store(true);
376	    return 0;
377	}
378	
379	UXB_RT_API const char* UXB_RT_CDECL __uxb_rt_task_status(int64_t handle) {
380	    std::lock_guard<std::mutex> lock(g_mutex);
381	    TaskRunV2* t = task_at_locked(handle);
382	    if (t && (t->state == TS_ERROR || t->state == TS_CANCELLED)) t->errorObserved = true;
383	    return hold_task_text(t ? state_name(t->state) : "PENDING");
384	}
385	
386	UXB_RT_API const char* UXB_RT_CDECL __uxb_rt_task_error(int64_t handle) {
387	    std::lock_guard<std::mutex> lock(g_mutex);
388	    TaskRunV2* t = task_at_locked(handle);
389	    if (t && !t->errorText.empty()) t->errorObserved = true;
390	    return hold_task_text(t ? t->errorText : std::string());
391	}
392	
393	UXB_RT_API int64_t UXB_RT_CDECL __uxb_rt_task_group_create(void) {
394	    std::lock_guard<std::mutex> lock(g_mutex);
395	    g_groups.push_back(std::make_unique<TaskGroupV2>());
396	    return static_cast<int64_t>(g_groups.size());
397	}
398	
399	UXB_RT_API int64_t UXB_RT_CDECL __uxb_rt_task_group_add(int64_t group, int64_t task) {
400	    std::lock_guard<std::mutex> lock(g_mutex);
401	    TaskGroupV2* g = group_at_locked(group);
402	    if (!g) runtime_fatal("TASKGROUP.ADD(): bos (NULL) grup tutamaci");
403	    if (!task_at_locked(task)) runtime_fatal("TASKGROUP.ADD(): arguman bir TASK olmali");
404	    g->members.push_back(task);
405	    return 0;
406	}
407	
408	UXB_RT_API int64_t UXB_RT_CDECL __uxb_rt_task_group_join(int64_t group) {
409	    std::vector<int64_t> members;
410	    {
411	        std::lock_guard<std::mutex> lock(g_mutex);
412	        TaskGroupV2* g = group_at_locked(group);
413	        if (!g) runtime_fatal("TASKGROUP.JOIN(): bos (NULL) grup tutamaci");
414	        members = g->members;
415	    }
416	    for (int64_t m : members) wait_finished(m);
417	    // Ilk hatali/iptal uye (ekleme sirasina gore) cagirana yukselir -- AST/MIR ile ayni.
418	    std::lock_guard<std::mutex> lock(g_mutex);
419	    for (int64_t m : members) {
420	        TaskRunV2* t = task_at_locked(m);
421	        if (t && (t->state == TS_ERROR || t->state == TS_CANCELLED)) {
422	            t->errorObserved = true;
423	            runtime_fatal(failure_message_locked(t));
424	        }
425	    }
426	    return 0;
427	}
428	
429	// K5: program sonu. normalExit=1: tum gorevleri bekle; 0: bitmemislere iptal iste, sonra bekle.
430	// Donus: 0 = temiz, 1 = okunmamis gorev hatasi vardi (hata cikisina yazildi; cikis kodu basarisiz olmali).
431	UXB_RT_API int64_t UXB_RT_CDECL __uxb_rt_task_shutdown(int64_t normalExit) {
432	    uxb::console_flush_current_thread();
433	    std::vector<int64_t> all;
434	    {
435	        std::lock_guard<std::mutex> lock(g_mutex);
436	        if (!g_poolStarted) return 0;
437	        for (auto& t : g_tasks) {
438	            if (!normalExit && !is_finished(t->state)) t->cancelRequested.store(true);
439	            all.push_back(t->id);
440	        }
441	    }
442	    for (int64_t id : all) wait_finished(id);
443	    int64_t unread = 0;
444	    {
445	        std::lock_guard<std::mutex> lock(g_mutex);
446	        for (auto& t : g_tasks) {
447	            // Iptal, programin kendi istegidir (hata degil); yalniz okunmamis ERROR raporlanir.
448	            if (t->state == TS_ERROR && !t->errorObserved) {
449	                const std::string msg = "okunmamis gorev hatasi (" + t->name + "): " + t->errorText;
450	                std::fputs(msg.c_str(), stderr);
451	                std::fputc('\n', stderr);
452	                unread = 1;
453	            }
454	        }
455	        std::fflush(stderr);
456	        g_stopping = true;
457	    }
458	    g_workAvailable.notify_all();
459	#if defined(_WIN32)
460	    for (HANDLE w : g_workers) {
461	        WaitForSingleObject(w, INFINITE);
462	        CloseHandle(w);
463	    }
464	    g_workers.clear();
465	#else
466	    for (auto& w : g_workers) {
467	        if (w.joinable()) w.join();
468	    }
469	#endif
470	    return unread;
471	}
472	
473	// S-156: rutin icindeki END. Ana is parcacigindan cagrilir (izolasyon denetimi gorev govdesinde END'i
474	// reddeder). K5 normal kapanisi: gorevler beklenir, okunmamis hata cikis kodunu 1 yapar.
475	UXB_RT_API int64_t UXB_RT_CDECL __uxb_rt_program_end(void) {
476	    uxb::console_flush_current_thread();
477	    const int64_t unread = __uxb_rt_task_shutdown(1);
478	    std::fflush(stdout);
479	    std::exit(unread ? 1 : 0);
480	}
481	
482	// K4: derleyicinin gomdugu isci sayisi; havuz acildiktan sonra etkisizdir.
483	UXB_RT_API int64_t UXB_RT_CDECL __uxb_rt_task_set_workers(int64_t count) {
484	    if (count >= 1 && count <= 1024) g_embeddedWorkers.store(static_cast<int>(count));
485	    return 0;
486	}
487	
488	UXB_RT_API int64_t UXB_RT_CDECL __uxb_rt_task_worker_count(void) {
489	    std::lock_guard<std::mutex> lock(g_mutex);
490	    return g_poolStarted ? g_workerCount : configured_worker_count();
491	}
492	
493	namespace uxb {
494	bool task_pool_active() { return g_poolActive.load(std::memory_order_relaxed); }
495	}  // namespace uxb

