"GXX=$gxx`r`nMINGW_ROOT=$mingwRoot`r`nPKGCONF=$pkgconf`r`nVARIANT=$Variant`r`nLIBUV=$useUv FLAGS=$($uv -join ' ')`r`nTBB=$useTbb FLAGS=$($tbb -join ' ')`r`nARGS=$($args -join ' ')`r`n" | Set-Content $log -Encoding UTF8
