1	param([Parameter(Mandatory=$true)][string]$File, [string]$Uxb = '.\bin\uxb_claude1_f2c.exe', [int]$NativeRepeat = 1, [string]$Workers = '')
2	$ErrorActionPreference = 'Continue'
3	foreach ($eng in 'AST', 'MIR') {
4	    $a = @('run', $File)
5	    if ($eng -eq 'MIR') { $a += @('--interpreter-backend', 'MIR') }
6	    $out = (& $Uxb @a 2>&1 | Where-Object { $_ -notmatch '^INFO' }) -join ' | '
7	    "{0,-4}: {1}" -f $eng, $out
8	}
9	$tmp = Join-Path $env:TEMP ('uxb_c1_' + [IO.Path]::GetFileNameWithoutExtension($File))
10	New-Item -ItemType Directory -Force $tmp | Out-Null
11	$b = (& $Uxb bld $File --out-root $tmp 2>&1) -join ' | '
12	$exe = (Get-ChildItem $tmp -Recurse -Filter program.exe | Sort-Object LastWriteTime -Descending | Select-Object -First 1)
13	if (-not $exe) { "x64 : BUILDFAIL " + ($b -replace 'INFO: [^|]*\|', ''); return }
14	Copy-Item (Join-Path (Split-Path $Uxb) 'uxb_runtime.dll') $exe.DirectoryName -Force
15	if ($Workers -ne '') { $env:UXB_TASK_WORKERS = $Workers }
16	$res = foreach ($i in 1..$NativeRepeat) {
17	    $o = (& $exe.FullName 2>&1) -join ' | '
18	    "$o [rc=$LASTEXITCODE]"
19	}
20	if ($Workers -ne '') { Remove-Item Env:UXB_TASK_WORKERS }
21	"x64 : " + (($res | Group-Object | ForEach-Object { if ($_.Count -gt 1) { "$($_.Name) x$($_.Count)" } else { $_.Name } }) -join ' ;; ')
22	Remove-Item -Recurse -Force $tmp -ErrorAction SilentlyContinue
