$b = (& $Uxb bld $File --out-root $tmp 2>&1) -join ' | '
$exe = (Get-ChildItem $tmp -Recurse -Filter program.exe | Sort-Object LastWriteTime -Descending | Select-Object -First 1)
if (-not $exe) { "x64 : BUILDFAIL " + ($b -replace 'INFO: [^|]*\|', ''); return }
Copy-Item (Join-Path (Split-Path $Uxb) 'uxb_runtime.dll') $exe.DirectoryName -Force
if ($Workers -ne '') { $env:UXB_TASK_WORKERS = $Workers }
$res = foreach ($i in 1..$NativeRepeat) {
    $o = (& $exe.FullName 2>&1) -join ' | '
    "$o [rc=$LASTEXITCODE]"
}
if ($Workers -ne '') { Remove-Item Env:UXB_TASK_WORKERS }
"x64 : " + (($res | Group-Object | ForEach-Object { if ($_.Count -gt 1) { "$($_.Name) x$($_.Count)" } else { $_.Name } }) -join ' ;; ')
Remove-Item -Recurse -Force $tmp -ErrorAction SilentlyContinue

