#               engeller (cikis 2): "dosyayi yeniden oku, degisikligin kime ait oldugunu kontrol et". Ayni dosya
#               icin ikinci deneme gecer (uyari verildi olarak isaretlenir).
#   -Mode post (PostToolUse Edit|Write|MultiEdit): bu oturumun yazdigi dosyanin yeni zaman damgasini kaydeder.
param([ValidateSet('pre','post')][string]$Mode = 'pre')
$ErrorActionPreference = 'Stop'
try { $payload = [Console]::In.ReadToEnd() | ConvertFrom-Json } catch { exit 0 }
$path = [string]$payload.tool_input.file_path
if ([string]::IsNullOrWhiteSpace($path) -or -not (Test-Path -LiteralPath $path)) { exit 0 }
$session = [string]$payload.session_id
if ($session -eq '') { $session = 'unknown' }

$stateDir = Join-Path $PSScriptRoot 'state'
if (-not (Test-Path $stateDir)) { New-Item -ItemType Directory -Force $stateDir | Out-Null }
$stateFile = Join-Path $stateDir ("coedit_" + ($session -replace '[^A-Za-z0-9_-]', '') + ".tsv")
$key = (Resolve-Path -LiteralPath $path).Path.ToLowerInvariant()
$mtime = (Get-Item -LiteralPath $path).LastWriteTimeUtc.Ticks

$state = @{}
if (Test-Path $stateFile) {
    foreach ($ln in Get-Content $stateFile) { $p = $ln -split "`t"; if ($p.Count -ge 2) { $state[$p[0]] = $p[1] } }
}
function Save-State { $state.GetEnumerator() | ForEach-Object { "$($_.Key)`t$($_.Value)" } | Set-Content $stateFile -Encoding utf8 }

if ($Mode -eq 'post') { $state[$key] = [string]$mtime; Save-State; exit 0 }

$ageMin = ((Get-Date).ToUniversalTime().Ticks - $mtime) / [TimeSpan]::TicksPerMinute
if ($ageMin -gt 20) { exit 0 }
if ($state.ContainsKey($key) -and ($state[$key] -eq [string]$mtime -or $state[$key] -eq "warned:$mtime")) { exit 0 }

$state[$key] = "warned:$mtime"; Save-State
[Console]::Error.WriteLine("UYARI (coedit_guard): $path son $([int]$ageMin) dakikada bu oturum disinda degisti (Codex / ikinci Claude / Mete). " +
    "Dosyayi yeniden oku, degisikligin kime ait oldugunu ve seninkiyle cakisip cakismadigini kontrol et; gerekiyorsa ai_koordinasyon'a not dus. " +
    "Tekrar denersen bu dosya icin gecer.")
exit 2

