def amac_isleri(args, ist: Istemci | None) -> int:
    rows, out_dir = pf.load_inventory()
    src = pf.SourceCache()
    cache = pf.load_cache(AMAC_CACHE)
    by_file: dict[str, list[dict]] = defaultdict(list)
    sigs: dict[str, list[str]] = defaultdict(list)
    skipped: dict[str, int] = defaultdict(int)
    for it in rows:
        if args.path_filter and args.path_filter.replace("\\", "/") not in it["file"]:
            continue
        lines = src.lines(it["file"])
        got = pf.extract_body(lines, it["line"], it["name"]) if lines else None
        if got is None:
            skipped["eskimis"] += 1
            continue
        mode, body = got
        if mode == "DECL":
            skipped["prototip"] += 1
            continue
        sigs[it["file"]].append(body.splitlines()[0].strip()[:160])
        k = pf.body_key(it, body)
        old = cache.get(k)
        if old and old.get("valid") and (old.get("source") in DIS_KAYNAKLAR or not args.llm_yenile):
            skipped["onbellekte"] += 1
            continue
        if pf.usable_comment(it.get("purpose") or ""):
            skipped["yorumlu"] += 1
            continue
        by_file[it["file"]].append({"it": it, "key": k, "body": body})
    total = sum(len(v) for v in by_file.values())
    print(f"[amac] harita {out_dir.name}: sorulacak rutin {total} ({len(by_file)} dosya)  atlanan: {dict(skipped)}", flush=True)
    flat = [x for f in sorted(by_file) for x in by_file[f]]
    if args.dry_run:
        n_req, cnt, size = 0, 0, 0
        for x in flat:
            b = min(len(x["body"]), 2400)
            if cnt and (cnt >= args.parti_rutin or size + b > args.parti_karakter):
                n_req, cnt, size = n_req + 1, 0, 0
            cnt, size = cnt + 1, size + b
        n_req += 1 if cnt else 0
        print(f"[amac] tahmini istek: {n_req}", flush=True)
        return 0
    if total == 0 or ist is None:
        return 0
    mimari = mimari_ozeti(3500)
    done, started = 0, time.time()
    with AMAC_CACHE.open("a", encoding="utf-8") as out:
        i = 0
        while i < len(flat):
            if args.max_dakika and (time.time() - started) / 60 >= args.max_dakika:
                print("[amac] süre doldu (kaldığı yerden devam eder)", flush=True)
                return done
            batch, size = [], 0
            while i < len(flat) and len(batch) < args.parti_rutin:
                b = pf.shorten(flat[i]["body"], 2400)
                if batch and size + len(b) > args.parti_karakter:
                    break
                batch.append((flat[i], b))
                size += len(b)
                i += 1
            files_in: list[str] = []
            for x, _b in batch:
                if x["it"]["file"] not in files_in:
                    files_in.append(x["it"]["file"])
            sig_budget = max(20, 120 // len(files_in))
            parts = [f"Mimari (kısa):\n{mimari}\n"]
            for f in files_in:
                parts.append(f"Dosya: {f}\nDosyadaki rutin imzaları:\n" + "\n".join(sigs[f][:sig_budget]) + "\n")
            parts.append("Amacı yazılacak rutinler:")
            for n, (x, b) in enumerate(batch, start=1):
                it = x["it"]
                parts.append(f"\n--- id {n}: {it['name']} ({it['file']} satır {it['line']}, kapsayıcı {it.get('container') or '-'})\n```freebasic\n{b}\n```")
            try:
                res = ist.sor(AMAC_SISTEM, "\n".join(parts), AMAC_SCHEMA, 8192)
            except ModelHata as e:
                dur_mesaji("amac", e)
                return done
            got: dict[int, str] = {}
            items = res.get("sonuclar", []) if isinstance(res, dict) else (res if isinstance(res, list) else [])
            for r in items:
                try:
                    got[int(r.get("id", 0))] = str(r.get("amac", ""))
                except (TypeError, ValueError, AttributeError):
                    continue
            for n, (x, _b) in enumerate(batch, start=1):
                ans = pf.clean_answer(got.get(n, ""))
                it = x["it"]
                rec = {"key": x["key"], "file": it["file"], "line": it["line"], "kind": it["kind"], "name": it["name"],
                       "container": it.get("container") or "", "signature": x["body"].splitlines()[0].strip()[:200],
                       "purpose": ans, "valid": not pf.is_uncertain(ans), "raw": got.get(n, "")[:400], "lang": "tr",
                       "source": ist.ad, "model": ist.model, "sec": 0, "ts": time.strftime("%Y-%m-%dT%H:%M:%S")}
                out.write(json.dumps(rec, ensure_ascii=False) + "\n")
            out.flush()
            done += len(batch)
            print(f"[amac] {done}/{total}  ({(time.time() - started) / 60:.1f} dk, bugün istek {ist.kota.count})  "
                  f"{', '.join(files_in)[:120]} +{len(batch)}", flush=True)
    return done


