    rpm = args.rpm or float(cfg.get(f"UXB_{up}_RPM", def_rpm))
    rpd = args.rpd if args.rpd >= 0 else int(cfg.get(f"UXB_{up}_RPD", def_rpd))
    has_key = bool(cfg.get(key_var))
    print(f"Sağlayıcı: {sag}  model: {model}  rpm={rpm:g}  rpd={rpd}  anahtar: {'var' if has_key else 'YOK'}  "
          f"(anahtar dosyası: {ANAHTAR_DOSYASI}{'' if ANAHTAR_DOSYASI.exists() else ' — YOK'})", flush=True)
    if not has_key and not args.dry_run:
        print(f"{key_var} tanımlı değil. Anahtarı {ANAHTAR_DOSYASI} dosyasındaki '{key_var}=' satırına yaz "
              f"(dosyanın başındaki açıklamaya bak). Plan görmek için --dry-run.")
