# ------------------------------------------------------------------ ayarlar
def ayarlari_oku() -> dict[str, str]:
    """Anahtar dosyasını (KEY=DEĞER satırları, # yorum) okur; ortam değişkenleri dosyanın önüne geçer."""
    cfg: dict[str, str] = {}
    if ANAHTAR_DOSYASI.exists():
        for ln in ANAHTAR_DOSYASI.read_text(encoding="utf-8-sig").splitlines():
            s = ln.strip()
            if not s or s.startswith("#") or "=" not in s:
                continue
            k, v = s.split("=", 1)
            v = v.strip().strip('"').strip("'")
            if v:
                cfg[k.strip()] = v
    for k, v in os.environ.items():
        if v and (k.endswith("_API_KEY") or k.startswith("UXB_") or k.endswith("_BASE_URL")):
            cfg[k] = v
    return cfg


def file_sha(text: str) -> str:
    return hashlib.sha1(text.encode("utf-8", errors="ignore")).hexdigest()


def load_jsonl(path: Path, key: str) -> dict[str, dict]:
    out: dict[str, dict] = {}
    if not path.exists():
        return out
    with path.open(encoding="utf-8") as f:
        for ln in f:
            ln = ln.strip()
            if not ln:
                continue
            try:
                rec = json.loads(ln)
                out[rec[key]] = rec
            except (json.JSONDecodeError, KeyError):
                continue
    return out


def mimari_ozeti(limit: int) -> str:
    try:
        return MIMARI.read_text(encoding="utf-8")[:limit]
    except OSError:
        return ""


def json_coz(text: str) -> object:
    """Model metninden JSON çıkarır (kod çiti ```json ... ``` ya da önünde/arkasında metin olabilir)."""
    t = text.strip()
    m = re.search(r"```(?:json)?\s*(.*?)```", t, re.S)
    if m:
        t = m.group(1).strip()
    try:
        return json.loads(t)
    except json.JSONDecodeError:
        s, e = t.find("{"), t.rfind("}")
        if s >= 0 and e > s:
            return json.loads(t[s:e + 1])
        raise


# ------------------------------------------------------------------ kota
class Kota:
    """Dakikalık/günlük/çalıştırma başına istek sınırı; günlük sayaç sağlayıcı başına diskte tutulur."""

    def __init__(self, saglayici: str, rpm: float, rpd: int, max_istek: int) -> None:
        self.state = V4 / "logs" / f"kota_{saglayici}.json"
        self.min_gap = 60.0 / max(0.1, rpm)
        self.rpd, self.max_istek = rpd, max_istek
        self.run_count, self.last = 0, 0.0
        self.day = time.strftime("%Y-%m-%d")
        self.count = 0
        try:
            st = json.loads(self.state.read_text(encoding="utf-8"))
            if st.get("gun") == self.day:
                self.count = int(st.get("istek", 0))
        except (OSError, ValueError):
            pass

    def bekle(self) -> str:
        if self.rpd and self.count >= self.rpd:
            return "GUNLUK_KOTA"
        if self.max_istek and self.run_count >= self.max_istek:
            return "CALISMA_SINIRI"
        gap = time.time() - self.last
        if gap < self.min_gap:
            time.sleep(self.min_gap - gap)
        self.last = time.time()
        return ""

    def say(self) -> None:
        self.count += 1
        self.run_count += 1
        self.state.parent.mkdir(parents=True, exist_ok=True)
        self.state.write_text(json.dumps({"gun": self.day, "istek": self.count}), encoding="utf-8")


class ModelHata(Exception):
    pass


# ------------------------------------------------------------------ sağlayıcılar
def gemini_semasi(schema: dict) -> dict:
    """Standart JSON Schema -> Gemini responseSchema (büyük harf tipler, additionalProperties yok)."""
    s = copy.deepcopy(schema)

    def walk(n: dict) -> dict:
        n.pop("additionalProperties", None)
        if "type" in n:
            n["type"] = n["type"].upper()
        for v in (n.get("properties") or {}).values():
            walk(v)
        if isinstance(n.get("items"), dict):
            walk(n["items"])
        return n

    return walk(s)


def http_json(url: str, body: dict, headers: dict, timeout: int = 300) -> dict:
    req = urllib.request.Request(url, data=json.dumps(body).encode("utf-8"),
                                 headers={"Content-Type": "application/json", **headers})
    with urllib.request.urlopen(req, timeout=timeout) as r:
        return json.load(r)


class Istemci:
    def __init__(self, saglayici: str, cfg: dict[str, str], model: str, kota: Kota) -> None:
        self.ad, self.cfg, self.model, self.kota = saglayici, cfg, model, kota
        self.key = cfg.get(SAGLAYICILAR[saglayici][0], "")
        self._claude = None

    def sor(self, system: str, user: str, schema: dict, max_tokens: int) -> object:
        stop = self.kota.bekle()
        if stop:
            raise ModelHata(stop)
        if self.ad == "claude":
            return self._claude_sor(system, user, schema, max_tokens)
        delay = 20.0
        for attempt in range(6):
            try:
                text = self._http_sor(system, user, schema, max_tokens)
                self.kota.say()
                return json_coz(text)
            except urllib.error.HTTPError as e:
                self.kota.say()
                msg = e.read().decode("utf-8", errors="replace")[:300]
                if e.code in (429, 500, 502, 503, 529) and attempt < 5:
                    print(f"   {self.ad} {e.code} (kota/yoğunluk) -> {delay:.0f} sn bekleniyor", flush=True)
                    time.sleep(delay)
                    delay = min(delay * 2, 300)
                    continue
                if e.code in (400, 401, 403, 404):
                    raise ModelHata(f"ANAHTAR_MODEL_YA_DA_ISTEK ({e.code}): {msg}")
                raise ModelHata(f"HTTP {e.code}: {msg}")
            except (urllib.error.URLError, TimeoutError, ConnectionError) as e:
                if attempt < 5:
                    print(f"   ağ hatası ({e}) -> {delay:.0f} sn", flush=True)
                    time.sleep(delay)
                    delay = min(delay * 2, 300)
                    continue
                raise ModelHata(f"AG: {e}")
            except (json.JSONDecodeError, KeyError, IndexError, TypeError) as e:
                raise ModelHata(f"CEVAP_COZULEMEDI: {e}")
        raise ModelHata("DENEME_BITTI")

    def _http_sor(self, system: str, user: str, schema: dict, max_tokens: int) -> str:
        if self.ad == "gemini":
            data = http_json(
                f"https://generativelanguage.googleapis.com/v1beta/models/{self.model}:generateContent",
                {"systemInstruction": {"parts": [{"text": system}]},
                 "contents": [{"role": "user", "parts": [{"text": user}]}],
                 "generationConfig": {"temperature": 0.2, "maxOutputTokens": max_tokens,
                                      "responseMimeType": "application/json",
                                      "responseSchema": gemini_semasi(schema)}},
                {"x-goog-api-key": self.key})
            cands = data.get("candidates") or []
            if not cands:
                raise ModelHata("BOS_CEVAP: " + json.dumps(data.get("promptFeedback", {}))[:200])
            return "".join(p.get("text", "") for p in cands[0].get("content", {}).get("parts") or [])
        if self.ad == "chatgpt":
            base = self.cfg.get("OPENAI_BASE_URL", "https://api.openai.com/v1").rstrip("/")
            data = http_json(
                base + "/chat/completions",
                {"model": self.model, "max_completion_tokens": max_tokens,
                 "messages": [{"role": "system", "content": system}, {"role": "user", "content": user}],
                 "response_format": {"type": "json_schema",
                                     "json_schema": {"name": "harita", "schema": schema, "strict": True}}},
                {"Authorization": f"Bearer {self.key}"})
            return data["choices"][0]["message"]["content"] or ""
        if self.ad == "kimi":
            base = self.cfg.get("MOONSHOT_BASE_URL", "https://api.moonshot.ai/v1").rstrip("/")
            sys_full = system + "\nCevabı YALNIZ şu JSON şemasına uyan tek bir JSON nesnesi olarak ver:\n" + json.dumps(schema, ensure_ascii=False)
            data = http_json(
                base + "/chat/completions",
                {"model": self.model, "max_tokens": max_tokens, "temperature": 0.2,
                 "messages": [{"role": "system", "content": sys_full}, {"role": "user", "content": user}],
                 "response_format": {"type": "json_object"}},
                {"Authorization": f"Bearer {self.key}"})
            return data["choices"][0]["message"]["content"] or ""
        raise ModelHata(f"bilinmeyen sağlayıcı {self.ad}")

    def _claude_sor(self, system: str, user: str, schema: dict, max_tokens: int) -> object:
        try:
            import anthropic  # resmi Anthropic Python SDK'sı (pip install anthropic)
        except ImportError:
            raise ModelHata("Claude için resmi paket kurulu değil: python -m pip install anthropic")
        if self._claude is None:
            self._claude = anthropic.Anthropic(api_key=self.key, max_retries=5)
        kwargs = {
            "model": self.model,
            "max_tokens": max_tokens,
            "system": system,
            "messages": [{"role": "user", "content": user}],
            "output_config": {"effort": self.cfg.get("UXB_CLAUDE_EFFORT", "low"),
                              "format": {"type": "json_schema", "schema": schema}},
        }
        try:
            if self.model.startswith(("claude-opus-5", "claude-fable-5")):
                # Güvenlik sınıflandırıcısı bir isteği reddederse sunucu aynı isteği yedek modelle yeniden çalıştırır.
                resp = self._claude.beta.messages.create(
                    betas=["server-side-fallback-2026-07-01"], fallbacks="default", **kwargs)
            else:
                resp = self._claude.messages.create(**kwargs)
        except anthropic.AuthenticationError:
            self.kota.say()
            raise ModelHata("ANAHTAR (Claude): ANTHROPIC_API_KEY geçersiz")
        except anthropic.NotFoundError:
            self.kota.say()
            raise ModelHata(f"MODEL (Claude): '{self.model}' bulunamadı")
        except anthropic.BadRequestError as e:
            self.kota.say()
            raise ModelHata(f"ISTEK (Claude): {e.message}")
        except anthropic.RateLimitError as e:
            self.kota.say()
            raise ModelHata(f"KOTA (Claude, SDK yeniden denemeleri bitti): {e.message}")
        except anthropic.APIStatusError as e:
            self.kota.say()
            raise ModelHata(f"HTTP {e.status_code} (Claude): {e.message}")
        except anthropic.APIConnectionError as e:
            raise ModelHata(f"AG (Claude): {e}")
        self.kota.say()
        if resp.stop_reason == "refusal":
            raise ModelHata("RED (Claude): istek güvenlik gerekçesiyle reddedildi")
        text = next((b.text for b in resp.content if b.type == "text"), "")
        try:
            return json.loads(text)
        except json.JSONDecodeError as e:
            raise ModelHata(f"CEVAP_COZULEMEDI (Claude, stop_reason={resp.stop_reason}): {e}")


def dur_mesaji(tag: str, e: ModelHata) -> None:
    s = str(e)
    if s == "GUNLUK_KOTA":
        print(f"[{tag}] günlük istek sınırı doldu; yarın kaldığı yerden devam.", flush=True)
    elif s == "CALISMA_SINIRI":
        print(f"[{tag}] bu çalıştırmanın istek sınırına (--max-istek) ulaşıldı.", flush=True)
    else:
        print(f"[{tag}] durdu: {s}", flush=True)


# ------------------------------------------------------------------ amac
AMAC_SCHEMA = {
    "type": "object",
    "properties": {"sonuclar": {"type": "array", "items": {
        "type": "object",
        "properties": {"id": {"type": "integer"}, "amac": {"type": "string"}},
        "required": ["id", "amac"], "additionalProperties": False}}},
    "required": ["sonuclar"], "additionalProperties": False,
}
AMAC_SISTEM = GENEL_BAGLAM + (
    "\nGörev: sana numaralı rutinler verilecek. Her biri için NE İŞE YARADIĞINI tek Türkçe cümleyle (en fazla 25 "
    "kelime) yaz. Cümle bir eylemle başlasın ('Bu rutin' ile başlamasın). Kodda görünen davranışı anlat; önemli "
    "yan etkiyi (global değişken, dosya, hata metni) belirt. Anlaşılmıyorsa yalnız 'belirsiz'. Çıktı: "
    "{\"sonuclar\": [{\"id\": numara, \"amac\": cümle}]}; her numara bir kez."
)


def amac_isleri(args, ist: Istemci | None) -> int:
    rows, out_dir = pf.load_inventory()
    src = pf.SourceCache()
    cache = pf.load_cache(AMAC_CACHE)
    by_file: dict[str, list[dict]] = defaultdict(list)
    sigs: dict[str, list[str]] = defaultdict(list)
    skipped: dict[str, int] = defaultdict(int)
    for it in rows:
        if args.path_filter and args.path_filter.replace("\\", "/") not in it["file"]:
            continue
        lines = src.lines(it["file"])
        got = pf.extract_body(lines, it["line"], it["name"]) if lines else None
        if got is None:
            skipped["eskimis"] += 1
            continue
        mode, body = got
        if mode == "DECL":
            skipped["prototip"] += 1
            continue
        sigs[it["file"]].append(body.splitlines()[0].strip()[:160])
        k = pf.body_key(it, body)
        old = cache.get(k)
        if old and old.get("valid") and (old.get("source") in DIS_KAYNAKLAR or not args.llm_yenile):
            skipped["onbellekte"] += 1
            continue
        if pf.usable_comment(it.get("purpose") or ""):
            skipped["yorumlu"] += 1
            continue
        by_file[it["file"]].append({"it": it, "key": k, "body": body})
    total = sum(len(v) for v in by_file.values())
    print(f"[amac] harita {out_dir.name}: sorulacak rutin {total} ({len(by_file)} dosya)  atlanan: {dict(skipped)}", flush=True)
    flat = [x for f in sorted(by_file) for x in by_file[f]]
    if args.dry_run:
        n_req, cnt, size = 0, 0, 0
        for x in flat:
            b = min(len(x["body"]), 2400)
            if cnt and (cnt >= args.parti_rutin or size + b > args.parti_karakter):
                n_req, cnt, size = n_req + 1, 0, 0
            cnt, size = cnt + 1, size + b
        n_req += 1 if cnt else 0
        print(f"[amac] tahmini istek: {n_req}", flush=True)
        return 0
    if total == 0 or ist is None:
        return 0
    mimari = mimari_ozeti(3500)
    done, started = 0, time.time()
    with AMAC_CACHE.open("a", encoding="utf-8") as out:
        i = 0
        while i < len(flat):
            if args.max_dakika and (time.time() - started) / 60 >= args.max_dakika:
                print("[amac] süre doldu (kaldığı yerden devam eder)", flush=True)
                return done
            batch, size = [], 0
            while i < len(flat) and len(batch) < args.parti_rutin:
                b = pf.shorten(flat[i]["body"], 2400)
                if batch and size + len(b) > args.parti_karakter:
                    break
                batch.append((flat[i], b))
                size += len(b)
                i += 1
            files_in: list[str] = []
            for x, _b in batch:
                if x["it"]["file"] not in files_in:
                    files_in.append(x["it"]["file"])
            sig_budget = max(20, 120 // len(files_in))
            parts = [f"Mimari (kısa):\n{mimari}\n"]
            for f in files_in:
                parts.append(f"Dosya: {f}\nDosyadaki rutin imzaları:\n" + "\n".join(sigs[f][:sig_budget]) + "\n")
            parts.append("Amacı yazılacak rutinler:")
            for n, (x, b) in enumerate(batch, start=1):
                it = x["it"]
                parts.append(f"\n--- id {n}: {it['name']} ({it['file']} satır {it['line']}, kapsayıcı {it.get('container') or '-'})\n```freebasic\n{b}\n```")
            try:
                res = ist.sor(AMAC_SISTEM, "\n".join(parts), AMAC_SCHEMA, 8192)
            except ModelHata as e:
                dur_mesaji("amac", e)
                return done
            got: dict[int, str] = {}
            items = res.get("sonuclar", []) if isinstance(res, dict) else (res if isinstance(res, list) else [])
            for r in items:
                try:
                    got[int(r.get("id", 0))] = str(r.get("amac", ""))
                except (TypeError, ValueError, AttributeError):
                    continue
            for n, (x, _b) in enumerate(batch, start=1):
                ans = pf.clean_answer(got.get(n, ""))
                it = x["it"]
                rec = {"key": x["key"], "file": it["file"], "line": it["line"], "kind": it["kind"], "name": it["name"],
                       "container": it.get("container") or "", "signature": x["body"].splitlines()[0].strip()[:200],
                       "purpose": ans, "valid": not pf.is_uncertain(ans), "raw": got.get(n, "")[:400], "lang": "tr",
                       "source": ist.ad, "model": ist.model, "sec": 0, "ts": time.strftime("%Y-%m-%dT%H:%M:%S")}
                out.write(json.dumps(rec, ensure_ascii=False) + "\n")
            out.flush()
            done += len(batch)
            print(f"[amac] {done}/{total}  ({(time.time() - started) / 60:.1f} dk, bugün istek {ist.kota.count})  "
                  f"{', '.join(files_in)[:120]} +{len(batch)}", flush=True)
    return done


# ------------------------------------------------------------------ modul (özet + SSS)
MODUL_SCHEMA = {
    "type": "object",
    "properties": {
        "ozet": {"type": "string"},
        "rol": {"type": "string"},
        "onemli_rutinler": {"type": "array", "items": {"type": "string"}},
        "sss": {"type": "array", "items": {
            "type": "object",
            "properties": {"soru": {"type": "string"}, "cevap": {"type": "string"}},
            "required": ["soru", "cevap"], "additionalProperties": False}},
    },
    "required": ["ozet", "rol", "onemli_rutinler", "sss"], "additionalProperties": False,
}
MODUL_SISTEM = GENEL_BAGLAM + (
    "\nGörev: bir kaynak dosyasını haritala.\n"
    "- 'ozet': 2-4 Türkçe cümle (dosyanın sorumluluğu, ana veri yapıları, kimlerle çalıştığı).\n"
    "- 'rol': derleme hattındaki yeri, tek kısa ifade (ör. 'parser: deyim ayrıştırma').\n"
    "- 'onemli_rutinler': en önemli 3-8 rutinin ADI (verilen listeden).\n"
    "- 'sss': bu dosya üzerinde çalışacak bir yapay zekâ ajanının soracağı 4-6 pratik soru ve cevabı "
    "(ör. 'X bu dosyada nerede işlenir?', 'Y hatası nereden gelir?', 'Z eklemek için hangi rutin değişmeli?'); "
    "cevaplar 1-3 cümle, somut rutin adlarına ve satır numaralarına dayansın; listede olmayanı uydurma."
)


def dosya_baglami(f: str, lines: list[str], rows: list[dict], amac: dict[str, str], limit: int) -> str:
    head = [ln.strip() for ln in lines[:80] if ln.strip().startswith(("'", "#"))]
    items = []
    for r in sorted((r for r in rows if r["file"] == f), key=lambda r: r["line"]):
        hdr = lines[r["line"] - 1].strip()[:170] if 0 < r["line"] <= len(lines) else r["name"]
        p = amac.get(f"{r['file']}|{r['name']}|{r['line']}", "")
        items.append(f"L{r['line']} {hdr}" + (f"  -- {p}" if p else ""))
    txt = (f"Dosya: {f} ({len(lines)} satır)\nBaş yorumları:\n" + "\n".join(head[:40]) +
           "\n\nRutinler (satır, imza, bilinen amaç):\n" + "\n".join(items))
    return txt[:limit]


def modul_isleri(args, ist: Istemci | None) -> int:
    rows, _out_dir = pf.load_inventory()
    src = pf.SourceCache()
    amac = {f"{r['file']}|{r['name']}|{r['line']}": r["purpose"]
            for r in pf.load_cache(AMAC_CACHE).values() if r.get("valid")}
    mcache = load_jsonl(MODUL_CACHE, "key")
    scache = load_jsonl(SSS_CACHE, "key")
    count_by_file: dict[str, int] = defaultdict(int)
    for r in rows:
        count_by_file[r["file"]] += 1
    todo = []
    for f in sorted(count_by_file):
        if args.path_filter and args.path_filter.replace("\\", "/") not in f:
            continue
        if count_by_file[f] < args.min_rutin:
            continue
        lines = src.lines(f)
        if not lines:
            continue
        k = f + "|" + file_sha("\n".join(lines))
        if k not in mcache or k not in scache:
            todo.append((f, lines, k, count_by_file[f]))
    todo.sort(key=lambda t: -t[3])
    print(f"[modul+sss] sorulacak dosya: {len(todo)} (en az {args.min_rutin} rutinli; dosya başına tek istek)", flush=True)
    if args.dry_run or not todo or ist is None:
        return 0
    mimari = mimari_ozeti(6000)
    done, started = 0, time.time()
    with MODUL_CACHE.open("a", encoding="utf-8") as mout, SSS_CACHE.open("a", encoding="utf-8") as sout:
        for f, lines, k, _n in todo:
            if args.max_dakika and (time.time() - started) / 60 >= args.max_dakika:
                print("[modul+sss] süre doldu", flush=True)
                break
            user = f"Mimari:\n{mimari}\n\n{dosya_baglami(f, lines, rows, amac, args.parti_karakter)}"
            try:
                res = ist.sor(MODUL_SISTEM, user, MODUL_SCHEMA, 6144)
            except ModelHata as e:
                dur_mesaji("modul+sss", e)
                break
            res = res if isinstance(res, dict) else {}
            meta = {"source": ist.ad, "model": ist.model, "ts": time.strftime("%Y-%m-%dT%H:%M:%S")}
            mrec = {"key": k, "file": f, "ozet": str(res.get("ozet", "")), "rol": str(res.get("rol", "")),
                    "onemli_rutinler": [str(x) for x in res.get("onemli_rutinler", [])][:8], **meta}
            srec = {"key": k, "file": f, "sss": [{"soru": str(q.get("soru", "")), "cevap": str(q.get("cevap", ""))}
                                                 for q in (res.get("sss") or []) if isinstance(q, dict)][:8], **meta}
            mout.write(json.dumps(mrec, ensure_ascii=False) + "\n")
            sout.write(json.dumps(srec, ensure_ascii=False) + "\n")
            mout.flush()
            sout.flush()
            done += 1
            print(f"[modul+sss] {done}/{len(todo)}  (bugün istek {ist.kota.count})  {f}", flush=True)
    return done


# ------------------------------------------------------------------ giriş
def main() -> int:
    ap = argparse.ArgumentParser(description="UXBc haritasını dış yapay zekâ ile doldurur (amaç / dosya özeti + SSS).")
    ap.add_argument("--saglayici", choices=sorted(SAGLAYICILAR), default="")
    ap.add_argument("--is", dest="is_", choices=["amac", "modul", "hepsi"], default="hepsi")
    ap.add_argument("--model", default="")
    ap.add_argument("--rpm", type=float, default=0, help="Dakikadaki en fazla istek (0 = sağlayıcı ayarı).")
    ap.add_argument("--rpd", type=int, default=-1, help="Günlük en fazla istek (0 = sınırsız, -1 = sağlayıcı ayarı).")
    ap.add_argument("--max-istek", type=int, default=0, help="Bu çalıştırmada en fazla istek (0 = sınırsız).")
    ap.add_argument("--max-dakika", type=float, default=0)
    ap.add_argument("--path-filter", default="")
    ap.add_argument("--parti-rutin", type=int, default=30)
    ap.add_argument("--parti-karakter", type=int, default=45000)
    ap.add_argument("--min-rutin", type=int, default=3)
    ap.add_argument("--llm-yenile", type=int, default=1)
    ap.add_argument("--dry-run", action="store_true")
    args = ap.parse_args()

    pf.raise_to_background_priority()
    cfg = ayarlari_oku()
    sag = args.saglayici or cfg.get("UXB_VARSAYILAN_SAGLAYICI", "gemini").lower()
    if sag not in SAGLAYICILAR:
        print(f"Bilinmeyen sağlayıcı '{sag}'. Seçenekler: {', '.join(sorted(SAGLAYICILAR))}")
        return 2
    key_var, def_model, def_rpm, def_rpd = SAGLAYICILAR[sag]
    up = sag.upper()
    model = args.model or cfg.get(f"UXB_{up}_MODEL", def_model)
    rpm = args.rpm or float(cfg.get(f"UXB_{up}_RPM", def_rpm))
    rpd = args.rpd if args.rpd >= 0 else int(cfg.get(f"UXB_{up}_RPD", def_rpd))
    has_key = bool(cfg.get(key_var))
    print(f"Sağlayıcı: {sag}  model: {model}  rpm={rpm:g}  rpd={rpd}  anahtar: {'var' if has_key else 'YOK'}  "
          f"(anahtar dosyası: {ANAHTAR_DOSYASI}{'' if ANAHTAR_DOSYASI.exists() else ' — YOK'})", flush=True)
    if not has_key and not args.dry_run:
        print(f"{key_var} tanımlı değil. Anahtarı {ANAHTAR_DOSYASI} dosyasındaki '{key_var}=' satırına yaz "
              f"(dosyanın başındaki açıklamaya bak). Plan görmek için --dry-run.")
        return 2
    ist = None if args.dry_run else Istemci(sag, cfg, model, Kota(sag, rpm, rpd, args.max_istek))
    for j in (["amac", "modul"] if args.is_ == "hepsi" else [args.is_]):
        n = amac_isleri(args, ist) if j == "amac" else modul_isleri(args, ist)
        if not args.dry_run:
            print(f"[{j}] bu çalıştırmada tamamlanan: {n}", flush=True)
            k = ist.kota
            if (k.rpd and k.count >= k.rpd) or (k.max_istek and k.run_count >= k.max_istek):
                break
    print("Bitti. Paketi yeniden kurmak için: python tools\\uxb_ajan_paketi.py", flush=True)
    return 0


if __name__ == "__main__":
    sys.exit(main())

