# -*- coding: utf-8 -*-
"""
UXBc harita belgelerini dışarıdaki bir yapay zekâ ile doldurur: Gemini, ChatGPT (OpenAI), Claude (Anthropic), Kimi
(Moonshot). Mete'nin kararı (2026-09-27/28): kaynak kod bu amaçla seçilen sağlayıcıya gönderilebilir; anahtarları
Mete kendisi girer.

İşler (--is):
  amac   Rutinlerin tek cümlelik Türkçe amacı.
  modul  Her kaynak dosyası için TEK istekte: 2-4 cümlelik özet + derleme hattındaki rolü + önemli rutinler + haritayı
         kullanacak ajanın soracağı 4-6 soru-cevap (SSS).
  hepsi  amac -> modul.

Gönderim (her istekte modülün TAMAMI gider; satır numaralı "dosya.txt" metni olarak):
  --gonderim modul   (varsayılan) istekte hedef modül(ler)in tam metni. Küçük modüller aynı isteğe birlikte girer.
  --gonderim paket   Kaynaklar klasör başına tek txt paketlerine (ajan_paketi/gonderim/*.txt; büyük klasörler ≤300 bin
                     karakterlik parçalara) toplanır. Gemini ve Claude'a her parça BİR KERE yüklenir (Files API) ve
                     sonraki isteklerde yalnız dosya kimliğiyle anılır; ChatGPT/Kimi'de parça metni istekle gider.
  Paketleri yalnız üretmek (başka araç/eklenti ile elle yüklemek için): --paket-uret

Sağlayıcı:
  --saglayici gemini|chatgpt|claude|kimi   tek sağlayıcı
  --saglayici zincir                       UXB_ZINCIR sırasıyla (varsayılan gemini,kimi,chatgpt,claude): biri günlük
                                           sınırına ya da anahtar/model hatasına ulaşınca sıradaki kaldığı yerden devam eder.
Sonuçlar `ajan_paketi/*_onbellek.jsonl`'a `source=<sağlayıcı>` ile yazılır; ardından: python tools\\uxb_ajan_paketi.py

Anahtarlar ve ayarlar: %USERPROFILE%\\.uxb\\api_anahtarlari.env (proje DIŞINDA). Aynı adlı ortam değişkeni dosyanın
önüne geçer. Anahtar URL'ye konmaz, istek başlığında gider.
"""
from __future__ import annotations

import argparse
import copy
import hashlib
import json
import os
import re
import sys
import time
import urllib.error
import urllib.request
from collections import defaultdict, deque
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent))
import uxb_purpose_fill as pf  # noqa: E402

V4 = pf.V4
WORKSPACE = pf.WORKSPACE
PKG = V4 / "ajan_paketi"
AMAC_CACHE = pf.DEFAULT_CACHE
MODUL_CACHE = PKG / "modul_ozet_onbellek.jsonl"
SSS_CACHE = PKG / "sss_onbellek.jsonl"
GONDERIM_DIR = PKG / "gonderim"
MIMARI = WORKSPACE / "uxb" / ".claude" / "skills" / "uxb-harita" / "MIMARI.md"
ANAHTAR_DOSYASI = Path(os.environ.get("USERPROFILE", str(Path.home()))) / ".uxb" / "api_anahtarlari.env"

SAGLAYICILAR = {
    # ad: (anahtar değişkeni, varsayılan model, rpm, rpd, dakikalık girdi token sınırı)
    "gemini": ("GEMINI_API_KEY", "gemini-2.5-flash", 8, 240, 230000),
    "chatgpt": ("OPENAI_API_KEY", "gpt-5-mini", 20, 100, 400000),
    "claude": ("ANTHROPIC_API_KEY", "claude-sonnet-5", 20, 100, 400000),
    "kimi": ("MOONSHOT_API_KEY", "kimi-k2-0905-preview", 10, 100, 300000),
}
DIS_KAYNAKLAR = set(SAGLAYICILAR)
PAKET_PARCA = 300_000     # bir paket parçasının üst sınırı (karakter)
YUKLEME_OMRU_SN = 46 * 3600  # Gemini dosyaları 48 saat yaşar; güvenli pay

GENEL_BAGLAM = (
    "Sen uXBasic adlı BASIC dili derleyicisinin kaynak kodunu inceleyen kıdemli bir derleyici mühendisisin. "
    "Kaynak FreeBASIC ile yazılmıştır (.fbs). Derleyicinin dört yürütme motoru vardır: AST yorumlayıcı, MIR "
    "yorumlayıcı, MIR tabanlı native x64 (NASM) ve eski AST-x64 kod üreticisi; ayrıca JS/WASM çıktısı. "
    "Sana modüllerin TAM metni satır numaralı ('L123| kod') verilir. Kısaltmaları olduğu gibi bırak (AST, MIR, HIR, "
    "x64, NASM, FFI, DLL). Yalnız verilen koddan çıkarılabilen şeyi yaz; emin değilsen 'belirsiz' de. Türkçe yaz. "
    "Yalnız istenen JSON'u döndür."
)


# ------------------------------------------------------------------ ayarlar / yardımcılar
def ayarlari_oku() -> dict[str, str]:
    """Anahtar dosyasını (KEY=DEĞER satırları, # yorum) okur; ortam değişkenleri dosyanın önüne geçer."""
    cfg: dict[str, str] = {}
    if ANAHTAR_DOSYASI.exists():
        for ln in ANAHTAR_DOSYASI.read_text(encoding="utf-8-sig").splitlines():
            s = ln.strip()
            if not s or s.startswith("#") or "=" not in s:
                continue
            k, v = s.split("=", 1)
            v = v.strip().strip('"').strip("'")
            if v:
                cfg[k.strip()] = v
    for k, v in os.environ.items():
        if v and (k.endswith("_API_KEY") or k.startswith("UXB_") or k.endswith("_BASE_URL")):
            cfg[k] = v
    return cfg


def file_sha(text: str) -> str:
    return hashlib.sha1(text.encode("utf-8", errors="ignore")).hexdigest()


def load_jsonl(path: Path, key: str) -> dict[str, dict]:
    out: dict[str, dict] = {}
    if not path.exists():
        return out
    with path.open(encoding="utf-8") as f:
        for ln in f:
            ln = ln.strip()
            if not ln:
                continue
            try:
                rec = json.loads(ln)
                out[rec[key]] = rec
            except (json.JSONDecodeError, KeyError):
                continue
    return out


def mimari_ozeti(limit: int) -> str:
    try:
        return MIMARI.read_text(encoding="utf-8")[:limit]
    except OSError:
        return ""


def modul_metni(rel: str, lines: list[str]) -> str:
    """Modülün tamamı, satır numaralı, 'dosya.txt' başlığıyla."""
    body = "\n".join(f"L{i}| {ln}" for i, ln in enumerate(lines, start=1))
    return f"===== DOSYA: {rel}  ({len(lines)} satır) =====\n{body}\n===== SON: {rel} =====\n"


def json_coz(text: str) -> object:
    t = text.strip()
    m = re.search(r"```(?:json)?\s*(.*?)```", t, re.S)
    if m:
        t = m.group(1).strip()
    try:
        return json.loads(t)
    except json.JSONDecodeError:
        s, e = t.find("{"), t.rfind("}")
        if s >= 0 and e > s:
            return json.loads(t[s:e + 1])
        raise


def slug(rel: str) -> str:
    return re.sub(r"[^A-Za-z0-9]+", "_", rel).strip("_")[:80] or "kok"


# ------------------------------------------------------------------ klasör paketleri
def paketleri_uret(files: list[str], src: "pf.SourceCache") -> dict[str, dict]:
    """Klasör başına tek txt (≤PAKET_PARCA karakterlik parçalar). Dönen: dosya -> {'parca': yol, 'sha': ...}."""
    GONDERIM_DIR.mkdir(parents=True, exist_ok=True)
    by_dir: dict[str, list[str]] = defaultdict(list)
    for f in sorted(files):
        by_dir[f.rsplit("/", 1)[0] if "/" in f else "."].append(f)
    index: dict[str, dict] = {}
    for d, fs in by_dir.items():
        parca_no, buf, members = 1, [], []

        def yaz() -> None:
            if not buf:
                return
            name = f"{slug(d)}__{parca_no:02d}.txt"
            text = f"##### uXBasic kaynak paketi: klasör {d}, parça {parca_no} #####\n" + "".join(buf)
            p = GONDERIM_DIR / name
            p.write_text(text, encoding="utf-8")
            sha = file_sha(text)
            for m in members:
                index[m] = {"parca": str(p), "sha": sha, "ad": name}

        for f in fs:
            lines = src.lines(f) or []
            t = modul_metni(f, lines)
            if buf and sum(len(x) for x in buf) + len(t) > PAKET_PARCA:
                yaz()
                parca_no, buf, members = parca_no + 1, [], []
            buf.append(t)
            members.append(f)
        yaz()
    (GONDERIM_DIR / "dizin.json").write_text(json.dumps(index, ensure_ascii=False, indent=1), encoding="utf-8")
    return index


# ------------------------------------------------------------------ kota
class Kota:
    """Dakikalık istek + dakikalık girdi token'ı + günlük/çalıştırma başına istek sınırı; günlük sayaç diskte."""

    def __init__(self, saglayici: str, rpm: float, rpd: int, tpm: int, max_istek: int) -> None:
        self.state = V4 / "logs" / f"kota_{saglayici}.json"
        self.min_gap = 60.0 / max(0.1, rpm)
        self.rpd, self.tpm, self.max_istek = rpd, tpm, max_istek
        self.run_count, self.last = 0, 0.0
        self.sent: deque[tuple[float, int]] = deque()
        self.day = time.strftime("%Y-%m-%d")
        self.count = 0
        try:
            st = json.loads(self.state.read_text(encoding="utf-8"))
            if st.get("gun") == self.day:
                self.count = int(st.get("istek", 0))
        except (OSError, ValueError):
            pass

    def bekle(self, chars: int) -> str:
        if self.rpd and self.count >= self.rpd:
            return "GUNLUK_KOTA"
        if self.max_istek and self.run_count >= self.max_istek:
            return "CALISMA_SINIRI"
        tokens = int(chars / 3.2) + 1
        while True:
            now = time.time()
            while self.sent and now - self.sent[0][0] > 60:
                self.sent.popleft()
            used = sum(t for _, t in self.sent)
            if not self.sent or not self.tpm or used + tokens <= self.tpm:
                break
            time.sleep(max(1.0, 60 - (now - self.sent[0][0]) + 0.5))
        gap = time.time() - self.last
        if gap < self.min_gap:
            time.sleep(self.min_gap - gap)
        self.last = time.time()
        self.sent.append((self.last, tokens))
        return ""

    def say(self) -> None:
        self.count += 1
        self.run_count += 1
        self.state.parent.mkdir(parents=True, exist_ok=True)
        self.state.write_text(json.dumps({"gun": self.day, "istek": self.count}), encoding="utf-8")


class ModelHata(Exception):
    """kind: KOTA (günlük sınır), SINIR (çalıştırma sınırı), KALICI (anahtar/model — sağlayıcı değiştir), GECICI."""

    def __init__(self, kind: str, msg: str) -> None:
        super().__init__(msg)
        self.kind = kind


# ------------------------------------------------------------------ sağlayıcı istemcisi
def gemini_semasi(schema: dict) -> dict:
    s = copy.deepcopy(schema)

    def walk(n: dict) -> dict:
        n.pop("additionalProperties", None)
        if "type" in n:
            n["type"] = n["type"].upper()
        for v in (n.get("properties") or {}).values():
            walk(v)
        if isinstance(n.get("items"), dict):
            walk(n["items"])
        return n

    return walk(s)


def http_json(url: str, body: dict, headers: dict, timeout: int = 600) -> dict:
    req = urllib.request.Request(url, data=json.dumps(body).encode("utf-8"),
                                 headers={"Content-Type": "application/json", **headers})
    with urllib.request.urlopen(req, timeout=timeout) as r:
        return json.load(r)


class Istemci:
    def __init__(self, saglayici: str, cfg: dict[str, str], model: str, kota: Kota) -> None:
        self.ad, self.cfg, self.model, self.kota = saglayici, cfg, model, kota
        self.key = cfg.get(SAGLAYICILAR[saglayici][0], "")
        self._claude = None
        self.yuk_path = V4 / "logs" / f"yuklemeler_{saglayici}.json"
        try:
            self.yuklemeler = json.loads(self.yuk_path.read_text(encoding="utf-8"))
        except (OSError, ValueError):
            self.yuklemeler = {}

    # ---- dosya yükleme (bir kere) ----
    def yukle(self, parca: dict) -> str | None:
        """Paket parçasını bir kere yükler; kimliğini döndürür. Desteklemeyen sağlayıcıda None (metin gider)."""
        if self.ad not in ("gemini", "claude"):
            return None
        rec = self.yuklemeler.get(parca["sha"])
        if rec and (self.ad == "claude" or time.time() - rec.get("t", 0) < YUKLEME_OMRU_SN):
            return rec["id"]
        data = Path(parca["parca"]).read_bytes()
        if self.ad == "gemini":
            start = urllib.request.Request(
                "https://generativelanguage.googleapis.com/upload/v1beta/files",
                data=json.dumps({"file": {"display_name": parca["ad"]}}).encode("utf-8"),
                headers={"x-goog-api-key": self.key, "X-Goog-Upload-Protocol": "resumable",
                         "X-Goog-Upload-Command": "start", "X-Goog-Upload-Header-Content-Length": str(len(data)),
                         "X-Goog-Upload-Header-Content-Type": "text/plain", "Content-Type": "application/json"})
            with urllib.request.urlopen(start, timeout=120) as r:
                up_url = r.headers.get("x-goog-upload-url")
            if not up_url:
                raise ModelHata("GECICI", "Gemini yükleme adresi alınamadı")
            put = urllib.request.Request(up_url, data=data, headers={
                "X-Goog-Upload-Offset": "0", "X-Goog-Upload-Command": "upload, finalize",
                "Content-Length": str(len(data))})
            with urllib.request.urlopen(put, timeout=600) as r:
                fid = json.load(r)["file"]["uri"]
        else:
            anthropic = self._claude_sdk()
            up = self._claude.files.upload(file=(parca["ad"], data, "text/plain"))
            fid = up.id
        self.yuklemeler[parca["sha"]] = {"id": fid, "t": time.time(), "ad": parca["ad"]}
        self.yuk_path.parent.mkdir(parents=True, exist_ok=True)
        self.yuk_path.write_text(json.dumps(self.yuklemeler, ensure_ascii=False, indent=1), encoding="utf-8")
        print(f"   [{self.ad}] paket yüklendi (bir kere): {parca['ad']}", flush=True)
        return fid

    # ---- soru ----
    def sor(self, system: str, user: str, schema: dict, max_tokens: int, dosya_id: str | None = None,
            ek_metin_uzunlugu: int = 0) -> object:
        stop = self.kota.bekle(len(system) + len(user) + ek_metin_uzunlugu)
        if stop == "GUNLUK_KOTA":
            raise ModelHata("KOTA", "günlük istek sınırı doldu")
        if stop == "CALISMA_SINIRI":
            raise ModelHata("SINIR", "bu çalıştırmanın istek sınırı (--max-istek) doldu")
        if self.ad == "claude":
            return self._claude_sor(system, user, schema, max_tokens, dosya_id)
        delay = 20.0
        for attempt in range(6):
            try:
                text = self._http_sor(system, user, schema, max_tokens, dosya_id)
                self.kota.say()
                return json_coz(text)
            except urllib.error.HTTPError as e:
                self.kota.say()
                msg = e.read().decode("utf-8", errors="replace")[:300]
                if e.code in (429, 500, 502, 503, 529) and attempt < 5:
                    if e.code == 429 and ("per day" in msg.lower() or "PerDay" in msg):
                        raise ModelHata("KOTA", f"{self.ad} sağlayıcı günlük kotası: {msg}")
                    print(f"   {self.ad} {e.code} (kota/yoğunluk) -> {delay:.0f} sn bekleniyor", flush=True)
                    time.sleep(delay)
                    delay = min(delay * 2, 300)
                    continue
                if e.code in (401, 402, 403, 404):
                    raise ModelHata("KALICI", f"ANAHTAR/MODEL/BAKİYE ({e.code}): {msg}")
                raise ModelHata("GECICI", f"HTTP {e.code}: {msg}")
            except (urllib.error.URLError, TimeoutError, ConnectionError) as e:
                if attempt < 5:
                    print(f"   ağ hatası ({e}) -> {delay:.0f} sn", flush=True)
                    time.sleep(delay)
                    delay = min(delay * 2, 300)
                    continue
                raise ModelHata("GECICI", f"AG: {e}")
            except (json.JSONDecodeError, KeyError, IndexError, TypeError) as e:
                raise ModelHata("GECICI", f"CEVAP_COZULEMEDI: {e}")
        raise ModelHata("GECICI", "DENEME_BITTI")

    def _http_sor(self, system: str, user: str, schema: dict, max_tokens: int, dosya_id: str | None) -> str:
        if self.ad == "gemini":
            parts = []
            if dosya_id:
                parts.append({"file_data": {"mime_type": "text/plain", "file_uri": dosya_id}})
            parts.append({"text": user})
            data = http_json(
                f"https://generativelanguage.googleapis.com/v1beta/models/{self.model}:generateContent",
                {"systemInstruction": {"parts": [{"text": system}]},
                 "contents": [{"role": "user", "parts": parts}],
                 "generationConfig": {"temperature": 0.2, "maxOutputTokens": max_tokens,
                                      "responseMimeType": "application/json",
                                      "responseSchema": gemini_semasi(schema)}},
                {"x-goog-api-key": self.key})
            cands = data.get("candidates") or []
            if not cands:
                raise ModelHata("GECICI", "BOS_CEVAP: " + json.dumps(data.get("promptFeedback", {}))[:200])
            return "".join(p.get("text", "") for p in cands[0].get("content", {}).get("parts") or [])
        if self.ad == "chatgpt":
            base = self.cfg.get("OPENAI_BASE_URL", "https://api.openai.com/v1").rstrip("/")
            data = http_json(
                base + "/chat/completions",
                {"model": self.model, "max_completion_tokens": max_tokens,
                 "messages": [{"role": "system", "content": system}, {"role": "user", "content": user}],
                 "response_format": {"type": "json_schema",
                                     "json_schema": {"name": "harita", "schema": schema, "strict": True}}},
                {"Authorization": f"Bearer {self.key}"})
            return data["choices"][0]["message"]["content"] or ""
        if self.ad == "kimi":
            base = self.cfg.get("MOONSHOT_BASE_URL", "https://api.moonshot.ai/v1").rstrip("/")
            sys_full = system + "\nCevabı YALNIZ şu JSON şemasına uyan tek bir JSON nesnesi olarak ver:\n" + json.dumps(schema, ensure_ascii=False)
            data = http_json(
                base + "/chat/completions",
                {"model": self.model, "max_tokens": max_tokens, "temperature": 0.2,
                 "messages": [{"role": "system", "content": sys_full}, {"role": "user", "content": user}],
                 "response_format": {"type": "json_object"}},
                {"Authorization": f"Bearer {self.key}"})
            return data["choices"][0]["message"]["content"] or ""
        raise ModelHata("KALICI", f"bilinmeyen sağlayıcı {self.ad}")

    def _claude_sdk(self):
        try:
            import anthropic  # resmi Anthropic Python SDK'sı
        except ImportError:
            raise ModelHata("KALICI", "Claude için resmi paket kurulu değil: python -m pip install anthropic")
        if self._claude is None:
            self._claude = anthropic.Anthropic(api_key=self.key, max_retries=5)
        return anthropic

    def _claude_sor(self, system: str, user: str, schema: dict, max_tokens: int, dosya_id: str | None) -> object:
        anthropic = self._claude_sdk()
        content: list[dict] = []
        if dosya_id:
            content.append({"type": "document", "source": {"type": "file", "file_id": dosya_id}})
        content.append({"type": "text", "text": user})
        kwargs = {
            "model": self.model,
            "max_tokens": max_tokens,
            "system": system,
            "messages": [{"role": "user", "content": content}],
            "output_config": {"effort": self.cfg.get("UXB_CLAUDE_EFFORT", "low"),
                              "format": {"type": "json_schema", "schema": schema}},
        }
        try:
            if self.model.startswith(("claude-opus-5", "claude-fable-5")):
                resp = self._claude.beta.messages.create(
                    betas=["server-side-fallback-2026-07-01"], fallbacks="default", **kwargs)
            else:
                resp = self._claude.messages.create(**kwargs)
        except anthropic.AuthenticationError:
            self.kota.say()
            raise ModelHata("KALICI", "ANAHTAR (Claude): ANTHROPIC_API_KEY geçersiz")
        except anthropic.PermissionDeniedError as e:
            self.kota.say()
            raise ModelHata("KALICI", f"İZİN/BAKİYE (Claude): {e.message}")
        except anthropic.NotFoundError:
            self.kota.say()
            raise ModelHata("KALICI", f"MODEL (Claude): '{self.model}' bulunamadı")
        except anthropic.BadRequestError as e:
            self.kota.say()
            kind = "KALICI" if "credit" in e.message.lower() else "GECICI"
            raise ModelHata(kind, f"ISTEK (Claude): {e.message}")
        except anthropic.RateLimitError as e:
            self.kota.say()
            raise ModelHata("GECICI", f"HIZ SINIRI (Claude, SDK yeniden denemeleri bitti): {e.message}")
        except anthropic.APIStatusError as e:
            self.kota.say()
            raise ModelHata("GECICI", f"HTTP {e.status_code} (Claude): {e.message}")
        except anthropic.APIConnectionError as e:
            raise ModelHata("GECICI", f"AG (Claude): {e}")
        self.kota.say()
        if resp.stop_reason == "refusal":
            raise ModelHata("GECICI", "RED (Claude): istek güvenlik gerekçesiyle reddedildi")
        text = next((b.text for b in resp.content if b.type == "text"), "")
        try:
            return json.loads(text)
        except json.JSONDecodeError as e:
            raise ModelHata("GECICI", f"CEVAP_COZULEMEDI (Claude, stop_reason={resp.stop_reason}): {e}")


