class Baglam:
    def __init__(self, args, src: "pf.SourceCache", files: list[str]) -> None:
        self.args, self.src = args, src
        self.index = paketleri_uret(files, src) if args.gonderim == "paket" else {}

    def hazirla(self, ist: Istemci | None, targets: list[str]) -> tuple[str, str | None, int]:
        """(istek metnine eklenecek modül metni, yüklü dosya kimliği, dosya kimliğiyle giden metin uzunluğu)."""
        if self.args.gonderim == "paket" and ist is not None:
            parcalar = {self.index[f]["parca"]: self.index[f] for f in targets if f in self.index}
            if len(parcalar) == 1:
                parca = next(iter(parcalar.values()))
                fid = ist.yukle(parca)
                if fid:
                    return (f"Kaynak metin ekteki paket dosyasındadır ({parca['ad']}); yalnız şu modüllere bak: "
                            f"{', '.join(targets)}.\n", fid, Path(parca["parca"]).stat().st_size)
                return (Path(parca["parca"]).read_text(encoding="utf-8") + "\n", None, 0)
        text = "".join(modul_metni(f, self.src.lines(f) or []) for f in targets)
        return (text, None, 0)


