        self.report_root.mkdir(parents=True, exist_ok=True)
        self._docs: Dict[Path, TextDocument] = {}
        self._original_bytes: Dict[Path, Optional[bytes]] = {}
        self._command_snapshots: List[Tuple[Command, Path, Optional[bytes]]] = []
        self.results: List[CommandResult] = []

    @staticmethod
    def sha256(data: Optional[bytes]) -> Optional[str]:
        return hashlib.sha256(data).hexdigest() if data is not None else None

    def _inside_root(self, path: Path) -> bool:
        try:
            path.resolve().relative_to(self.root)
            return True
        except ValueError:
            return False

    def resolve_target(self, command: Command, for_new: bool = False) -> Path:
        target_text = command.target.strip().replace("\\", "/")
        if not target_text:
            raise PatchError(f"Emir {command.seq}: hedef dosya boş.")

        target_rel = Path(target_text)
        if target_rel.is_absolute():
            candidate = target_rel.resolve()
        elif command.path_context:
            candidate = (self.root / command.path_context / target_rel).resolve()
        elif "/" in target_text:
            candidate = (self.root / target_rel).resolve()
        elif for_new:
            candidate = (self.root / target_rel).resolve()
        else:
            matches = [p.resolve() for p in self.root.rglob(target_text) if p.is_file()]
            if not matches:
                raise PatchError(f"Emir {command.seq}: dosya bulunamadı: {target_text}")
            if len(matches) > 1:
                rels = ", ".join(str(p.relative_to(self.root)) for p in matches[:10])
                raise PatchError(
                    f"Emir {command.seq}: dosya adı benzersiz değil: {target_text}. "
                    f"#P(...) veya göreli tam yol kullanın. Eşleşmeler: {rels}"
                )
            candidate = matches[0]

        if not self._inside_root(candidate):
            raise PatchError(f"Emir {command.seq}: hedef kök klasör dışına çıkıyor: {candidate}")
        if candidate.suffix.lower() not in ALLOWED_EXTENSIONS:
            raise PatchError(
                f"Emir {command.seq}: desteklenmeyen uzantı {candidate.suffix!r}: {candidate}"
            )
        return candidate

    def _load_doc(self, path: Path, for_new: bool = False) -> TextDocument:
        if path in self._docs:
            return self._docs[path]
        if path.exists():
            data = path.read_bytes()
            doc = TextDocument.from_bytes(data)
            self._original_bytes[path] = data
        elif for_new:
            doc = TextDocument.new("")
            self._original_bytes[path] = None
        else:
            raise PatchError(f"Dosya bulunamadı: {path}")
        self._docs[path] = doc
        return doc

    @staticmethod
    def _norm_line(line: str, mode: str) -> str:
        if mode == MODE_STRICT:
            return line
        return line.strip()

    def _find_sequences(
        self,
        lines: Sequence[str],
        needle: Sequence[str],
        mode: str,
        start: int = 0,
        end: Optional[int] = None,
    ) -> List[int]:
        if not needle:
            raise PatchError("Boş referans bloğu kullanılamaz.")
        end = len(lines) if end is None else end
        n = len(needle)
        normalized_needle = [self._norm_line(x, mode) for x in needle]
        found: List[int] = []
        for idx in range(start, max(start, end - n + 1)):
            part = lines[idx : idx + n]
            if [self._norm_line(x, mode) for x in part] == normalized_needle:
                found.append(idx)
        return found

    @staticmethod
    def _lines(block: str) -> List[str]:
        return block.split("\n") if block != "" else []

    def _unique_block(self, lines: Sequence[str], block: str, mode: str, label: str) -> Tuple[int, int]:
        needle = self._lines(block)
        matches = self._find_sequences(lines, needle, mode)
        if len(matches) == 0:
            raise PatchError(f"{label}: referans kod bulunamadı.")
        if len(matches) > 1:
            raise PatchError(f"{label}: referans kod {len(matches)} kez bulundu; yama belirsiz.")
        return matches[0], len(needle)

    @staticmethod
    def _parse_anchor(reference: str) -> Tuple[List[str], List[str], str]:
        lines = reference.split("\n")
        markers: List[Tuple[int, int, int, str]] = []
        dynamic = re.compile(r"^\$(\d+)\.i\.(\d+)\$$", re.I)
        legacy_variable = re.compile(r"^\$\.i\.\$$", re.I)
        legacy_fixed = re.compile(r"^\$(\d+)\.\.\.(\d+)\$$")

        for idx, line in enumerate(lines):
            token = line.strip()
            m = dynamic.match(token)
            if m:
                markers.append((idx, int(m.group(1)), int(m.group(2)), token))
                continue
            if legacy_variable.match(token):
                markers.append((idx, idx, len(lines) - idx - 1, token))
                continue
            m = legacy_fixed.match(token)
            if m:
                markers.append((idx, int(m.group(1)), int(m.group(2)), token))

        if len(markers) != 1:
            raise PatchError(
                "Hassas yamada tam bir çapa markerı gerekir: $n.i.m$ "
                "(geriye uyumlu: $.i.$ veya $n...m$)."
            )
        idx, upper_count, lower_count, marker = markers[0]
        if upper_count <= 0 or lower_count <= 0:
            raise PatchError("Çapa satır sayıları sıfırdan büyük olmalıdır.")
        if idx < upper_count or len(lines) - idx - 1 < lower_count:
            raise PatchError(
                f"{marker}: marker çevresinde istenen kadar satır yok "
                f"(üst={upper_count}, alt={lower_count})."
            )
        upper = lines[idx - upper_count : idx]
        lower = lines[idx + 1 : idx + 1 + lower_count]
        return upper, lower, marker

    def _unique_region(
        self, lines: Sequence[str], reference: str, mode: str, label: str
    ) -> Tuple[int, int, str]:
        upper, lower, marker = self._parse_anchor(reference)
        upper_matches = self._find_sequences(lines, upper, mode)
        regions: List[Tuple[int, int]] = []
        for up in upper_matches:
            middle_start = up + len(upper)
            lower_matches = self._find_sequences(lines, lower, mode, start=middle_start)
            for low in lower_matches:
                regions.append((middle_start, low))
        unique_regions = sorted(set(regions))
        if not unique_regions:
            raise PatchError(f"{label}: {marker} çapaları dosyada bulunamadı.")
        if len(unique_regions) > 1:
            raise PatchError(
                f"{label}: {marker} çapaları {len(unique_regions)} farklı bölgeyi eşliyor; yama belirsiz."
            )
        return unique_regions[0][0], unique_regions[0][1], marker

    def _snapshot(self, command: Command, path: Path) -> None:
        current: Optional[bytes]
        if path in self._docs:
            current = self._docs[path].to_bytes()
        elif path.exists():
            current = path.read_bytes()
        else:
            current = None
        self._command_snapshots.append((command, path, current))

    def apply_command(self, command: Command) -> None:
        is_new = command.kind == "NEW"
        path = self.resolve_target(command, for_new=is_new)
        existed = path.exists() or (path in self._original_bytes and self._original_bytes[path] is not None)
        if is_new and existed:
            raise PatchError(f"Emir {command.seq}: yeni dosya zaten var: {path.relative_to(self.root)}")
        if not is_new and not path.exists() and path not in self._docs:
            raise PatchError(f"Emir {command.seq}: hedef dosya yok: {path.relative_to(self.root)}")

        doc = self._load_doc(path, for_new=is_new)
        self._snapshot(command, path)
        before = doc.to_bytes() if existed or doc.text else None
        before_text = doc.text
        note = ""

        if command.kind == "NEW":
            doc.text = command.body
            note = "Yeni dosya oluşturuldu."
        elif command.kind == "BLOCK":
            lines = doc.text.split("\n")
            idx, count = self._unique_block(
                lines, command.reference, command.mode, f"Emir {command.seq}"
            )
            replacement = self._lines(command.body)
            doc.text = "\n".join(lines[:idx] + replacement + lines[idx + count :])
            note = f"Benzersiz {count} satırlık blok değiştirildi."
        elif command.kind == "RANGE_SET":
            lines = doc.text.split("\n")
            start, end, marker = self._unique_region(
                lines, command.reference, command.mode, f"Emir {command.seq}"
            )
            replacement = self._lines(command.body)
            doc.text = "\n".join(lines[:start] + replacement + lines[end:])
            note = f"{marker} arasındaki {end-start} satır, {len(replacement)} satırla değiştirildi."
        elif command.kind == "DELETE":
            lines = doc.text.split("\n")
            start, end, marker = self._unique_region(
                lines, command.reference, command.mode, f"Emir {command.seq}"
            )
            if command.body == "":
                removed = end - start
                doc.text = "\n".join(lines[:start] + lines[end:])
                note = f"{marker} arasındaki {removed} satır silindi."
            else:
                delete_lines = self._lines(command.body)
                matches = self._find_sequences(lines, delete_lines, command.mode, start, end)
                if len(matches) == 0:
                    raise PatchError(f"Emir {command.seq}: silinecek blok çapa bölgesinde bulunamadı.")
                if len(matches) > 1:
                    raise PatchError(
                        f"Emir {command.seq}: silinecek blok çapa bölgesinde {len(matches)} kez bulundu."
                    )
                idx = matches[0]
                doc.text = "\n".join(lines[:idx] + lines[idx + len(delete_lines) :])
                note = f"{marker} bölgesindeki {len(delete_lines)} satır silindi."
        else:
            raise PatchError(f"Bilinmeyen emir türü: {command.kind}")

        after = doc.to_bytes()
        changed = before_text != doc.text or (is_new and not existed)
        self.results.append(
            CommandResult(
                seq=command.seq,
                kind=command.kind,
                target=command.target,
                resolved_path=str(path.relative_to(self.root)).replace("\\", "/"),
                mode=command.mode,
                before_sha256=self.sha256(before),
                after_sha256=self.sha256(after),
                existed_before=existed,
                changed=changed,
                note=note,
            )
        )

    def simulate(self, commands: Sequence[Command]) -> None:
        for command in commands:
            self.apply_command(command)
        unchanged = [r for r in self.results if not r.changed]
        if unchanged:
            details = ", ".join(f"Emir {r.seq} ({r.resolved_path})" for r in unchanged)
            raise PatchError(f"Yama no-op üretti; kaynak zaten aynı olabilir: {details}")

    def combined_diff(self) -> str:
        chunks: List[str] = []
        for path in sorted(self._docs, key=lambda p: str(p)):
            original = self._original_bytes.get(path)
            final = self._docs[path].to_bytes()
            if original == final:
                continue
            old_text = "" if original is None else TextDocument.from_bytes(original).text
            new_text = self._docs[path].text
            rel = str(path.relative_to(self.root)).replace("\\", "/")
            diff = difflib.unified_diff(
                old_text.splitlines(keepends=True),
                new_text.splitlines(keepends=True),
                fromfile=("/dev/null" if original is None else f"a/{rel}"),
                tofile=f"b/{rel}",
                lineterm="",
            )
            chunks.extend(line + ("" if line.endswith("\n") else "\n") for line in diff)
        return "".join(chunks)

    def _transaction_name(self) -> str:
        return datetime.now().strftime("%Y%m%d_%H%M%S_%f")

    def _write_log(self, payload: dict) -> None:
        path = self.report_root / SESSION_LOG
        with path.open("a", encoding="utf-8") as handle:
            handle.write(json.dumps(payload, ensure_ascii=False) + "\n")

    def commit(self, commands: Sequence[Command], script_path: Path) -> Path:
        # Simülasyondan sonra kaynak başka süreçte değişti mi?
        for path, original in self._original_bytes.items():
            current = path.read_bytes() if path.exists() else None
            if current != original:
                raise PatchError(
                    f"Uygulama öncesi kaynak değişti: {path.relative_to(self.root)}. Yeniden dry-run yapın."
                )

        tx = self.history_root / self._transaction_name()
        (tx / "files").mkdir(parents=True)
        (tx / "commands").mkdir(parents=True)
        (tx / "stage").mkdir(parents=True)

        manifest = {
            "schema": "uxb-yama-transaction-4",
            "version": VERSION,
            "created_at": datetime.now().isoformat(timespec="seconds"),
            "root": str(self.root),
            "status": "prepared",
            "active_command_count": len(commands),
            "commands": [],
            "files": [],
        }

        shutil.copy2(script_path, tx / "emir.txt")
        diff_text = self.combined_diff()
        (tx / "diff.patch").write_text(diff_text, encoding="utf-8")
        (self.report_root / LAST_DIFF).write_text(diff_text, encoding="utf-8")

        for path, original in self._original_bytes.items():
            rel = str(path.relative_to(self.root)).replace("\\", "/")
            safe = base64.urlsafe_b64encode(rel.encode("utf-8")).decode("ascii").rstrip("=")
            backup_name = f"{safe}.before"
            if original is not None:
                (tx / "files" / backup_name).write_bytes(original)
            final = self._docs[path].to_bytes()
            stage_path = tx / "stage" / rel
            stage_path.parent.mkdir(parents=True, exist_ok=True)
            stage_path.write_bytes(final)
            manifest["files"].append(
                {
                    "path": rel,
                    "existed_before": original is not None,
                    "backup": backup_name if original is not None else None,
                    "before_sha256": self.sha256(original),
                    "after_sha256": self.sha256(final),
                }
            )

        for index, (command, path, before) in enumerate(self._command_snapshots, start=1):
            rel = str(path.relative_to(self.root)).replace("\\", "/")
            snap_name = f"{index:04d}.before"
            if before is not None:
                (tx / "commands" / snap_name).write_bytes(before)
            cmd_data = asdict(command)
            cmd_data.update(
                {
                    "resolved_path": rel,
                    "before_exists": before is not None,
                    "before_snapshot": snap_name if before is not None else None,
                    "result": asdict(self.results[index - 1]),
                }
            )
            manifest["commands"].append(cmd_data)

        manifest_path = tx / "manifest.json"
        manifest_path.write_text(json.dumps(manifest, ensure_ascii=False, indent=2), encoding="utf-8")

        applied_paths: List[Path] = []
        try:
            for path in self._docs:
                final = self._docs[path].to_bytes()
                path.parent.mkdir(parents=True, exist_ok=True)
                tmp = path.with_name(f".{path.name}.yamav4.{uuid.uuid4().hex}.tmp")
                with tmp.open("wb") as handle:
                    handle.write(final)
                    handle.flush()
                    os.fsync(handle.fileno())
                os.replace(tmp, path)
                applied_paths.append(path)
        except Exception as exc:
            # Bütün transaction başlangıç durumunu geri yükle.
            for path, original in self._original_bytes.items():
                try:
                    if original is None:
                        if path.exists():
                            path.unlink()
                    else:
                        path.parent.mkdir(parents=True, exist_ok=True)
                        path.write_bytes(original)
                except Exception:
                    pass
            manifest["status"] = "apply_failed_restored"
            manifest["error"] = repr(exc)
            manifest_path.write_text(json.dumps(manifest, ensure_ascii=False, indent=2), encoding="utf-8")
            raise PatchError(f"Disk yazma başarısız; başlangıç durumu geri yüklendi: {exc}") from exc

        manifest["status"] = "applied"
        manifest["applied_at"] = datetime.now().isoformat(timespec="seconds")
        manifest_path.write_text(json.dumps(manifest, ensure_ascii=False, indent=2), encoding="utf-8")
        self._write_log(
            {
                "event": "APPLY",
                "transaction": tx.name,
                "root": str(self.root),
                "command_count": len(commands),
                "files": [r.resolved_path for r in self.results],
            }
        )
        return tx

    def _transactions(self) -> List[Path]:
        if not self.history_root.exists():
            return []
        return sorted(
            [p for p in self.history_root.iterdir() if p.is_dir() and (p / "manifest.json").exists()],
            reverse=True,
        )

    def latest_active_transaction(self) -> Tuple[Path, dict]:
        for tx in self._transactions():
            manifest = json.loads((tx / "manifest.json").read_text(encoding="utf-8"))
            if manifest.get("status") in {"applied", "partially_rolled_back"}:
                return tx, manifest
        raise PatchError("Geri alınabilecek aktif transaction bulunamadı.")

    def rollback_last_transaction(self) -> Path:
        tx, manifest = self.latest_active_transaction()
        for file_info in manifest["files"]:
            path = self.root / file_info["path"]
            if file_info["existed_before"]:
                data = (tx / "files" / file_info["backup"]).read_bytes()
                path.parent.mkdir(parents=True, exist_ok=True)
                path.write_bytes(data)
            elif path.exists():
                path.unlink()
        manifest["status"] = "rolled_back"
        manifest["active_command_count"] = 0
        manifest["rolled_back_at"] = datetime.now().isoformat(timespec="seconds")
        (tx / "manifest.json").write_text(json.dumps(manifest, ensure_ascii=False, indent=2), encoding="utf-8")
        self._write_log({"event": "ROLLBACK_TRANSACTION", "transaction": tx.name})
        return tx

    def rollback_last_commands(self, count: int) -> Path:
        if count <= 0:
            raise PatchError("Geri alınacak emir sayısı sıfırdan büyük olmalıdır.")
        tx, manifest = self.latest_active_transaction()
        active = int(manifest.get("active_command_count", len(manifest["commands"])))
        if count > active:
            raise PatchError(f"Yalnız {active} aktif emir var; {count} emir geri alınamaz.")
        for idx in range(active - 1, active - count - 1, -1):
            cmd = manifest["commands"][idx]
            path = self.root / cmd["resolved_path"]
            if cmd["before_exists"]:
                data = (tx / "commands" / cmd["before_snapshot"]).read_bytes()
                path.parent.mkdir(parents=True, exist_ok=True)
                path.write_bytes(data)
            elif path.exists():
                path.unlink()
        active -= count
        manifest["active_command_count"] = active
        manifest["status"] = "rolled_back" if active == 0 else "partially_rolled_back"
        manifest["last_command_rollback_at"] = datetime.now().isoformat(timespec="seconds")
        (tx / "manifest.json").write_text(json.dumps(manifest, ensure_ascii=False, indent=2), encoding="utf-8")
        self._write_log(
            {"event": "ROLLBACK_COMMANDS", "transaction": tx.name, "count": count, "remaining": active}
        )
        return tx

    def history_summary(self) -> List[dict]:
        rows: List[dict] = []
        for tx in self._transactions():
            manifest = json.loads((tx / "manifest.json").read_text(encoding="utf-8"))
            rows.append(
                {
                    "transaction": tx.name,
                    "status": manifest.get("status"),
                    "active_commands": manifest.get("active_command_count"),
                    "total_commands": len(manifest.get("commands", [])),
                    "created_at": manifest.get("created_at"),
                }
            )
        return rows


def load_settings(workspace: Path) -> dict:
    path = workspace / DEFAULT_SETTINGS
    if not path.exists():
        return {}
    try:
        return json.loads(path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError):
        return {}

