# gerçek başlangıcı hiç aranmıyordu -> emir SESSİZCE atlanıyordu. Her kalıp her olası konumdan aranır;
# hangi adayın kabul edileceğine aşağıdaki "en erken başlayan, öncelikli" seçimi karar verir.
for priority, kind, pattern in self._patterns:
    pos = 0
    while True:
        match = pattern.search(script, pos)
        if not match:
            break
        pos = match.start() + 1
        if is_commented(match.start()):
            continue
        groups = {k: (v or "") for k, v in match.groupdict().items()}
        candidates.append(Candidate(match.start(), match.end(), priority, kind, groups))

