        return "HATA"
    return "FARKLI"


def dogrula(uxb, p):
    bas = oku(p)
    sonuc = {"dosya": os.path.relpath(p, KOK).replace("\\", "/"), **bas, "motor": {}}
    for ad, ek in (("AST", []), ("MIR", ["--interpreter-backend", "MIR"])):
        rc, c = calistir([uxb, "run", p] + ek)
        s = temizle(c)
        sonuc["motor"][ad] = {"durum": karar(rc, s, bas["beklenen"]), "cikti": s[:40], "rc": rc}
