# -*- coding: utf-8 -*-
"""UxbRAG tools\*.py dosyalarını ÇALIŞTIRMADAN okur: derleme sınaması, başlık açıklaması, komut satırı bayrakları."""
import ast, sys, json, pathlib

kok = pathlib.Path(sys.argv[1])
cikti = []
for p in sorted(kok.glob("*.py")):
    kayit = {"dosya": p.name, "bayt": p.stat().st_size}
    try:
        kaynak = p.read_text(encoding="utf-8", errors="replace")
        agac = ast.parse(kaynak)
        kayit["derlenir"] = True
    except SyntaxError as e:
        kayit["derlenir"] = False
        kayit["hata"] = f"satır {e.lineno}: {e.msg}"
        cikti.append(kayit)
        continue
    kayit["docstring"] = (ast.get_docstring(agac) or "").strip().splitlines()[:6]
    ust = [s.strip() for s in kaynak.splitlines()[:14] if s.strip().startswith("#")]
    kayit["ust_yorum"] = ust[:8]
    bay = []
    for n in ast.walk(agac):
        if isinstance(n, ast.Call) and isinstance(n.func, ast.Attribute) and n.func.attr == "add_argument":
            adlar = [a.value for a in n.args if isinstance(a, ast.Constant) and isinstance(a.value, str)]
            ek = {}
            for k in n.keywords:
                if k.arg in ("default", "help", "choices", "action", "type", "required", "nargs"):
                    try:
                        ek[k.arg] = ast.literal_eval(k.value)
                    except Exception:
                        ek[k.arg] = "<ifade>"
            bay.append({"adlar": adlar, **ek})
    kayit["bayraklar"] = bay
    kayit["main_var"] = "__main__" in kaynak
    kayit["ice_aktardiklari"] = sorted({(a.module or "").split(".")[0] if isinstance(a, ast.ImportFrom) else al.name.split(".")[0]
                                        for a in ast.walk(agac) if isinstance(a, (ast.Import, ast.ImportFrom))
                                        for al in (a.names if isinstance(a, ast.Import) else [a])
                                        } - {""})
    kayit["yerel_ice_aktarma"] = [m for m in kayit["ice_aktardiklari"] if (kok / (m + ".py")).exists() or (kok / m).is_dir()]
    cikti.append(kayit)
print(json.dumps(cikti, ensure_ascii=False, indent=1))

