def read_text(p: Path) -> str:
    b = p.read_bytes()
    for enc in ("utf-8-sig", "cp1254", "latin-1"):
        try:
            return b.decode(enc)
        except UnicodeDecodeError:
            continue
    return b.decode("utf-8", errors="replace")


def iter_source_files(roots: list[str]) -> list[Path]:
    seen: set[Path] = set()
    res: list[Path] = []
    for r in roots:
        base = WORKSPACE / r
        if base.is_file():
            if base not in seen:
                seen.add(base)
                res.append(base)
            continue
        if not base.exists():
            continue
        for p in sorted(base.rglob("*")):
            if not p.is_file() or p.suffix.lower() not in BASIC_EXTS:
                continue
            parts = {x.lower() for x in p.relative_to(base).parts[:-1]}
            if parts & SKIP_DIRS:
                continue
            if any(x.lower().startswith("tekdosyaklsoru") for x in p.parts):
                continue
            try:
                if p.stat().st_size > MAX_FILE_BYTES:
                    continue
            except OSError:
                continue
            if p not in seen:
                seen.add(p)
                res.append(p)
    return res


def build_all(files: list[Path]) -> Ctx:
    ctx = Ctx()
    ctx.models = []  # type: ignore[attr-defined]
    for p in files:
        rel = p.relative_to(WORKSPACE).as_posix()
        ctx.models.append(parse_structure(rel, read_text(p)))  # type: ignore[attr-defined]
    for fm in ctx.models:  # type: ignore[attr-defined]
        ctx.routines.extend(fm.routines)
        ctx.types.extend(fm.types)
        ctx.vars.extend(fm.vars)
        ctx.namespaces |= fm.namespaces
        if fm.mainbody:
            ctx.routines.append(
                {"id": None, "kind": "MODÜL", "name": "(modül gövdesi)", "ns": "", "container": "", "file": fm.rel,
                 "line": fm.mainbody[0][0], "end_line": fm.mainbody[-1][0], "proto": False, "mods": [], "access": "",
                 "lib": "", "alias": "", "conv": "", "params": [], "ret": "", "doc": [], "trail": "", "body": fm.mainbody,
                 "body_doc": []}
            )
    ctx.routines.sort(key=lambda r: (r["file"], r["line"], r["name"]))
    for i, r in enumerate(ctx.routines, 1):
        r["id"] = f"R{i:05d}"
    ctx.types.sort(key=lambda t: (t["file"], t["line"]))
    for i, t in enumerate(ctx.types, 1):
        t["id"] = f"T{i:04d}"
        t["used_by"] = []
    ctx.vars.sort(key=lambda v: (v["file"], v["line"]))
    for i, v in enumerate(ctx.vars, 1):
        v["id"] = f"G{i:05d}"
        v["readers"] = set()
        v["writers"] = set()
    ns_lower = {n.lower() for n in ctx.namespaces} | {x.split(".")[-1].lower() for x in ctx.namespaces}
    for t in ctx.types:
        if t["name"]:
            ctx.type_by_name.setdefault(t["name"].lower(), t)
    for r in ctx.routines:
        c = r["container"].lower()
        if c and c not in ctx.type_by_name and c in ns_lower:
            r["ns"] = r["container"]
            r["container"] = ""
    for r in ctx.routines:
        if r["kind"] == "MODÜL":
            continue
        if r["container"]:
            ctx.methods_of[r["container"].lower()][r["name"].lower()].append(r)
            t = ctx.type_by_name.get(r["container"].lower())
            if t is not None and not any(x is r for x in t["methods"]):
                t["methods"].append(r)
        else:
            ctx.by_name[r["name"].lower()].append(r)
    ctx.const_by_name = collections.defaultdict(list)  # type: ignore[attr-defined]
    for v in ctx.vars:
        if v["scope"] == "GLOBAL":
            ctx.global_by_name[v["name"].lower()].append(v)
        elif v["scope"] == "CONST":
            ctx.const_by_name[v["name"].lower()].append(v)  # type: ignore[attr-defined]
    for t in ctx.types:
        if t["kind"] == "ENUM":
            for m in t["members"]:
                ctx.const_by_name[m["name"].lower()].append(  # type: ignore[attr-defined]
                    {"name": m["name"], "enum": t["name"], "kind": "ENUM", "file": t["file"]}
                )
    return ctx


def analyze_all(ctx: Ctx):
    tables: list[dict] = []
    known_ns = {n.split(".")[-1].lower() for n in ctx.namespaces} | {n.lower() for n in ctx.namespaces}
    for r in ctx.routines:
        if r["proto"]:
            r.update({"locals": [], "decisions": 0, "cc": 1, "stmt_count": 0, "returns": 0, "ret_assign": False,
                      "calls_raw": collections.Counter(), "dll": [], "ext_calls": {}, "amb_methods": {}, "g_read": [],
                      "g_write": [], "p_write": [], "fields_read": [], "fields_write": [], "c_used": [], "types_used": []})
            # prototipte kullanılan tipler
            tn = set()
            for t in [p["type"] for p in r["params"]] + [r["ret"]]:
                for w in re.findall(r"[A-Za-z_]\w*", t or ""):
                    if w.lower() in ctx.type_by_name:
                        tn.add(ctx.type_by_name[w.lower()]["name"])
            r["types_used"] = sorted(tn)
            continue
        label = f"{r['container']+'.' if r['container'] else ''}{r['name']}"
        analyze_body(r, r["body"], ctx, known_ns, tables, label)
    tables.sort(key=lambda t: (t["file"], t["line"]))
    for i, t in enumerate(tables, 1):
        t["id"] = f"TB{i:05d}"
    by_id = {r["id"]: r for r in ctx.routines}
    for r in ctx.routines:
        r["callees"] = {}
        r["callers"] = {}
    for r in ctx.routines:
        for (_, cid), n in r["calls_raw"].items():
            if cid in by_id:
                r["callees"][cid] = r["callees"].get(cid, 0) + n
                by_id[cid]["callers"][r["id"]] = by_id[cid]["callers"].get(r["id"], 0) + n
        for g in r["g_read"]:
            for v in ctx.global_by_name.get(g, []):
                v["readers"].add(r["id"])
        for g in r["g_write"]:
            for v in ctx.global_by_name.get(g, []):
                v["writers"].add(r["id"])
        for tname in r["types_used"]:
            t = ctx.type_by_name.get(tname.lower())
            if t is not None:
                t["used_by"].append(r["id"])
    ctx.tables = tables  # type: ignore[attr-defined]
    ctx.by_id = by_id  # type: ignore[attr-defined]
    return tables


def resolve_include(from_rel: str, target: str, all_rel: set[str], by_base: dict[str, list[str]]):
    import posixpath
    t = target.replace("\\", "/")
    cand = posixpath.normpath(posixpath.join(posixpath.dirname(from_rel), t))
    if cand in all_rel:
        return cand
    t2 = t.lstrip("./")
    while t2.startswith("../"):
        t2 = t2[3:]
    parts = t2.split("/")
    for k in range(len(parts)):
        suf = "/".join(parts[k:])
        hits = [x for x in all_rel if x.endswith("/" + suf) or x == suf]
        if len(hits) == 1:
            return hits[0]
        if len(hits) > 1 and k == 0:
            return sorted(hits)[0]
    b = by_base.get(parts[-1].lower(), [])
    if len(b) == 1:
        return b[0]
    return None


def module_graph(ctx: Ctx):
    models = ctx.models  # type: ignore[attr-defined]
    all_rel = {fm.rel for fm in models}
    by_base: dict[str, list[str]] = collections.defaultdict(list)
    for x in all_rel:
        by_base[x.rsplit("/", 1)[-1].lower()].append(x)
    edges: dict[str, set[str]] = {fm.rel: set() for fm in models}
    unresolved: dict[str, list[str]] = collections.defaultdict(list)
    for fm in models:
        for inc in fm.includes:
            tgt = resolve_include(fm.rel, inc["target"], all_rel, by_base)
            inc["resolved"] = tgt
            if tgt and tgt != fm.rel:
                edges[fm.rel].add(tgt)
            elif not tgt:
                unresolved[fm.rel].append(inc["target"])
    # Tarjan SCC (yinelemesiz)
    index = {}
    low = {}
    onstack = set()
    stack: list[str] = []
    sccs: list[list[str]] = []
    counter = [0]
    for root in sorted(edges):
        if root in index:
            continue
        work = [(root, iter(sorted(edges[root])))]
        index[root] = low[root] = counter[0]
        counter[0] += 1
        stack.append(root)
        onstack.add(root)
        while work:
            v, it = work[-1]
            adv = False
            for w in it:
                if w not in index:
                    index[w] = low[w] = counter[0]
                    counter[0] += 1
                    stack.append(w)
                    onstack.add(w)
                    work.append((w, iter(sorted(edges.get(w, ())))))
                    adv = True
                    break
                elif w in onstack:
                    low[v] = min(low[v], index[w])
            if adv:
                continue
            work.pop()
            if work:
                low[work[-1][0]] = min(low[work[-1][0]], low[v])
            if low[v] == index[v]:
                comp = []
                while True:
                    w = stack.pop()
                    onstack.discard(w)
                    comp.append(w)
                    if w == v:
                        break
                sccs.append(sorted(comp))
    comp_of = {}
    for ci, comp in enumerate(sccs):
        for m in comp:
            comp_of[m] = ci
    # katman: bir modülün katmanı = 1 + en yüksek (include ettiklerinin katmanı); döngü grubu tek düğüm
    comp_edges: dict[int, set[int]] = collections.defaultdict(set)
    for a, outs in edges.items():
        for b in outs:
            if comp_of[a] != comp_of[b]:
                comp_edges[comp_of[a]].add(comp_of[b])
    layer_c: dict[int, int] = {}

    def lay(c: int) -> int:
        if c in layer_c:
            return layer_c[c]
        layer_c[c] = 0
        v = 0
        for d in comp_edges.get(c, ()):
            v = max(v, 1 + lay(d))
        layer_c[c] = v
        return v

    for c in range(len(sccs)):
        lay(c)
    layer = {m: layer_c[comp_of[m]] for m in edges}
    rev: dict[str, set[str]] = {m: set() for m in edges}
    for a, outs in edges.items():
        for b in outs:
            rev[b].add(a)
    cycles = [c for c in sccs if len(c) > 1]
    ctx.mod_edges, ctx.mod_rev, ctx.mod_layer = edges, rev, layer  # type: ignore[attr-defined]
    ctx.mod_cycles, ctx.mod_unresolved = cycles, unresolved  # type: ignore[attr-defined]
    return edges, rev, layer, cycles


