def load_purposes():
    rows: dict[tuple, list[dict]] = collections.defaultdict(list)
    p = V4 / "ajan_paketi" / "rutinler.tsv"
    if p.exists():
        with p.open("r", encoding="utf-8", errors="replace", newline="") as f:
            rd = csv.reader(f, delimiter="\t", quoting=csv.QUOTE_NONE)
            head = next(rd, None)
            for row in rd:
                if len(row) < 8:
                    continue
                d = dict(zip(head, row))
                try:
                    ln = int(d.get("satir", "0") or 0)
                except ValueError:
                    ln = 0
                rows[(d["dosya"], d["ad"].lower())].append(
                    {"satir": ln, "tur": d.get("tur", ""), "kaynak": d.get("kaynak", ""), "amac": d.get("amac", ""),
                     "kapsayici": d.get("kapsayici", "")}
                )
    mods: dict[str, dict] = {}
    mp = V4 / "ajan_paketi" / "modul_ozet_onbellek.jsonl"
    if mp.exists():
        for line in mp.open("r", encoding="utf-8", errors="replace"):
            try:
                d = json.loads(line)
            except ValueError:
                continue
            if d.get("file"):
                mods[d["file"]] = d
    return rows, mods


def attach_purposes(ctx: Ctx):
    rows, mods = load_purposes()
    ctx.mod_ozet = mods  # type: ignore[attr-defined]
    hit = 0
    for r in ctx.routines:
        r["amac"], r["amac_kaynak"] = "", ""
        cands = rows.get((r["file"], r["name"].lower()), [])
        want_proto = r["proto"]
        best = None
        for c in cands:
            is_proto = c["tur"].endswith("*")
            score = abs(c["satir"] - r["line"]) + (0 if is_proto == want_proto else 100000)
            if c["amac"] and (best is None or score < best[0]):
                best = (score, c)
        if best and best[0] < 100000:
            r["amac"], r["amac_kaynak"] = best[1]["amac"], best[1]["kaynak"] or "yorum"
            hit += 1
        elif r["doc"] or r["trail"] or r.get("body_doc"):
            txt = squash(" ".join(r["doc"] or r.get("body_doc") or []) or r["trail"], 200)
            if txt:
                r["amac"], r["amac_kaynak"] = txt, "yorum"
    # prototip için tanımdan miras
    for r in ctx.routines:
        if r["proto"] and not r["amac"]:
            for d in ctx.by_name.get(r["name"].lower(), []):
                if not d["proto"] and d.get("amac"):
                    r["amac"], r["amac_kaynak"] = d["amac"], d["amac_kaynak"] + "(tanımdan)"
                    break
    return hit

