# -*- coding: utf-8 -*-
import html, re, sys
from pathlib import Path

md = Path(sys.argv[1]).read_text(encoding="utf-8").splitlines()
out_path = Path(sys.argv[2])


def inline(s: str) -> str:
    s = html.escape(s, quote=False)
    s = re.sub(r"`([^`]+)`", r"<code>\1</code>", s)
    s = re.sub(r"\*\*([^*]+)\*\*", r"<strong>\1</strong>", s)
    return s


def pill(cell_html: str) -> str:
    low = re.sub(r"<[^>]+>", "", cell_html).lower()
    if low.startswith("çalışıyor") or low.startswith("hepsi denendi"):
        return f'<span class="ok">{cell_html}</span>'
    if low.startswith("denenmedi") or "denenmedi" in low[:30]:
        return f'<span class="warn">{cell_html}</span>'
    if low.startswith("kullanma") or low.startswith("artık gerekmiyor"):
        return f'<span class="mute">{cell_html}</span>'
    return cell_html


body = []
i = 0
title_h1 = ""
while i < len(md):
    ln = md[i]
    if ln.startswith("```"):
        j = i + 1
        code = []
        while j < len(md) and not md[j].startswith("```"):
            code.append(md[j])
            j += 1
        body.append('<div class="scroll"><pre><code>' + html.escape("\n".join(code)) + "</code></pre></div>")
        i = j + 1
        continue
    if ln.startswith("# "):
        title_h1 = ln[2:]
        body.append(f"<h1>{inline(ln[2:])}</h1>")
    elif ln.startswith("## "):
        body.append(f"<h2>{inline(ln[3:])}</h2>")
    elif ln.startswith("|"):
        rows = []
        while i < len(md) and md[i].startswith("|"):
            rows.append([c.strip() for c in md[i].strip().strip("|").split("|")])
            i += 1
        head, data = rows[0], [r for r in rows[2:]]
        st = [k for k, h in enumerate(head) if h.lower() in ("durum",)]
        t = ['<div class="scroll"><table><thead><tr>' + "".join(f"<th>{inline(h)}</th>" for h in head) + "</tr></thead><tbody>"]
        for r in data:
            cells = []
            for k, c in enumerate(r):
                h = inline(c)
                cells.append(f"<td>{pill(h) if k in st else h}</td>")
            t.append("<tr>" + "".join(cells) + "</tr>")
        t.append("</tbody></table></div>")
        body.append("".join(t))
        continue
    elif ln.startswith("- "):
        items = []
        while i < len(md) and md[i].startswith("- "):
            items.append(f"<li>{inline(md[i][2:])}</li>")
            i += 1
        body.append("<ul>" + "".join(items) + "</ul>")
        continue
    elif ln.strip():
        buf = [ln]
        i += 1
        while i < len(md) and md[i].strip() and not md[i].startswith(("#", "|", "- ", "```")):
            buf.append(md[i])
            i += 1
        txt = inline(" ".join(buf))
        cls = ' class="callout"' if txt.startswith("<strong>Bu gece dikkat") else ""
        body.append(f"<p{cls}>{txt}</p>")
        continue
    i += 1

