$U = "C:\Users\mete\Downloads\BasicOyunSource\UXBc_Clean\UXBc"
$sw = Get-Date
"=== tekdosyaklsoru klasörleri (derinlik sınırı yok; node_modules/.venv/chroma hariç) ==="
$bul = New-Object System.Collections.Generic.List[string]
$kuyruk = New-Object System.Collections.Generic.Queue[string]; $kuyruk.Enqueue($U)
while ($kuyruk.Count) {
  $d = $kuyruk.Dequeue()
  try { $alt = [IO.Directory]::GetDirectories($d) } catch { continue }
  foreach ($a in $alt) {
    $ad = [IO.Path]::GetFileName($a)
    if ($ad -in 'node_modules','.venv','chroma_db','chroma_db_core','.git','__pycache__','site-packages') { continue }
    if ($ad -like 'tekdosya*') { $bul.Add($a) } 
    $kuyruk.Enqueue($a)
  }
}
foreach ($b in $bul) {
  $paket = Join-Path $b 'paketler'
  $pk = if (Test-Path $paket) { @(Get-ChildItem $paket -File -ErrorAction SilentlyContinue) } else { @() }
  $n = (Get-ChildItem $b -Recurse -File -ErrorAction SilentlyContinue | Measure-Object Length -Sum)
  "{0}`n     {1} dosya, {2:N1} MB, son yazım {3}, paket: {4}" -f $b.Replace("$U\",''), $n.Count, ($n.Sum/1MB), (Get-Item $b).LastWriteTime.ToString('yyyy-MM-dd'), $pk.Count
}
"toplam $($bul.Count) klasör; tarama süresi {0:N0} sn" -f ((Get-Date)-$sw).TotalSeconds

